// Pomocná funkce pro formátování data pro DatePicker (YYYY-MM-DD formát)
const formatDateForPicker = (date) => {
  if (!date) return '';
  const d = new Date(date);
  if (isNaN(d.getTime())) return '';
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

// Pomocná funkce pro normalizaci textu - odstranění diakritiky a převod na malá písmena
const normalizeText = (text) => {
  if (!text) return '';
  return text
    .toLowerCase()
    .normalize('NFD') // Rozloží diakritiku na základní znaky + kombinující znaky
    .replace(/[\u0300-\u036f]/g, '') // Odstraní kombinující znaky (diakritiku)
    .replace(/[^\w\s]/g, '') // Odstraní interpunkci
    .trim();
};

// Globální pomocná funkce pro aktuální datum ve formátu YYYY-MM-DD
const getCurrentDateFormatted = () => {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

/**
 * 🎨 Z-INDEX HIERARCHIE PRO ORDERFORM25
 *
 * Přehled všech z-index hodnot pro správné vrstvení komponent:
 *
 * 1-100:     Základní elementy (headers, shadows, atd.)
 * 10000:     Dropdown menu (CustomSelect, MultiSelect)
 * 99999:     Fullscreen režim (Container.isFullscreen)
 * 100000:    Dialogy nad fullscreenem (SupplierAddDialog, AresPopup, SupplierPopup, DeleteConfirm)
 * 999999:    Nejvyšší vrstva (ConfirmDialog, TemplateModal, LoadingOverlay, PreviewModal)
 *
 * ⚠️ DŮLEŽITÉ: Dialogy a modály MUSÍ mít vyšší z-index než fullscreen (99999),
 *              aby se zobrazovaly i když je formulář ve fullscreen módu!
 */

const Container = styled.div`
  background: #f8fafc;
  padding: 0;
  position: fixed;
  top: ${props => props.isFullscreen ? '0' : 'var(--app-fixed-offset-actual, calc(var(--app-header-height, 96px) + var(--app-menu-height, 48px)))'};
  left: 0;
  right: 0;
  bottom: ${props => props.isFullscreen ? '0' : 'var(--app-footer-height, 54px)'};
  width: 100%;
  height: ${props => props.isFullscreen ? '100vh' : 'calc(100vh - var(--app-fixed-offset-actual, calc(var(--app-header-height, 96px) + var(--app-menu-height, 48px))) - var(--app-footer-height, 54px))'};
  overflow: hidden;
  z-index: ${props => props.isFullscreen ? '99999' : 'auto'};
  transition: all 0.3s ease-in-out;

  /* Animace pro loading spinner */
  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
`;

