const SectionHeader = styled.div`
  padding: 1rem 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: all 0.3s ease;

  /* Barevné schéma podle typu sekce */
  ${props => {
    // Určí základní barvu podle typu sekce
    const getBaseColors = (sectionTheme) => {
      switch(sectionTheme) {
        case 'section-grey':
          return {
            bg: ['#f9fafb', '#f3f4f6'],
            border: '#9ca3af',
            hover: ['#f3f4f6', '#e5e7eb']
          };
        case 'section-orange':
          return {
            bg: ['#fef3c7', '#fde68a'],
            border: '#f59e0b',
            hover: ['#fde68a', '#facc15']
          };
        case 'section-blue':
          return {
            bg: ['#dbeafe', '#bfdbfe'],
            border: '#3b82f6',
            hover: ['#bfdbfe', '#93c5fd']
          };
        case 'section-purple':
          return {
            bg: ['#f3e8ff', '#e9d5ff'],
            border: '#a855f7',
            hover: ['#e9d5ff', '#d8b4fe']
          };
        case 'section-red':
          return {
            bg: ['#fee2e2', '#fecaca'],
            border: '#dc2626',
            hover: ['#fecaca', '#fca5a5']
          };
        default:
          return {
            bg: ['#fef3c7', '#fde68a'],
            border: '#f59e0b',
            hover: ['#fde68a', '#facc15']
          };
      }
    };

    const colors = getBaseColors(props.sectionTheme);

    // Upraví intenzitu podle toho, jestli je sekce aktivní
    const opacity = props.isActive ? '1' : '0.6';

    return `
      background: linear-gradient(135deg, ${colors.bg[0]} 0%, ${colors.bg[1]} 100%);
      border-bottom: 1px solid ${colors.border};
      opacity: ${opacity};

      &:hover {
        background: linear-gradient(135deg, ${colors.hover[0]} 0%, ${colors.hover[1]} 100%);
        opacity: 1;
      }
    `;
  }}
`;

