// Currency Input Component - Zachovává pozici kurzoru při psaní
function CurrencyInput({ fieldName, value, onChange, onBlur, disabled, hasError, placeholder }) {
  const inputRef = useRef(null);
  const [localValue, setLocalValue] = useState('');
  const [isFocused, setIsFocused] = useState(false);

  // Funkce pro formátování měny (BEZ Kč, protože to je fixně vpravo)
  const formatCurrency = (val) => {
    if (!val && val !== 0) return '';
    const num = parseFloat(val.toString().replace(/[^0-9.-]/g, ''));
    if (isNaN(num)) return '';
    // Pro faktury/účetnictví přesně 2 desetinná místa
    return num.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ' ').replace('.', ',');
  };

  // Inicializace lokální hodnoty z props (pouze když není focused)
  useEffect(() => {
    if (!isFocused) {
      const formattedValue = formatCurrency(value || '');
      if (localValue !== formattedValue) {
        setLocalValue(formattedValue);
      }
    }
  }, [value, isFocused]);

  const handleChange = (e) => {
    const newValue = e.target.value;

    // Aktualizovat lokální hodnotu okamžitě (bez formátování)
    setLocalValue(newValue);

    // 🔧 FIX: Před odesláním do onChange očistit hodnotu od formátování
    // Parsovat a vrátit jako string s tečkou (ne čárkou) pro konzistentní ukládání
    const cleanValue = newValue.replace(/[^\d,.-]/g, '').replace(',', '.');
    const numValue = parseFloat(cleanValue);
    const finalValue = isNaN(numValue) ? '' : numValue.toFixed(2);

    // ⚡ VOLAT onChange při každém znaku pro přepočet DPH s očištěnou hodnotou
    onChange(fieldName, finalValue);
  };

  const handleFocus = () => {
    setIsFocused(true);
  };

  const handleBlurLocal = () => {
    setIsFocused(false);

    // Formátovat hodnotu při ztrátě fokusu (BEZ Kč)
    const formatted = formatCurrency(localValue);
    setLocalValue(formatted);

    // 🔧 FIX: Před odesláním do onBlur očistit hodnotu od formátování
    const cleanValue = localValue.replace(/[^\d,.-]/g, '').replace(',', '.');
    const numValue = parseFloat(cleanValue);
    const finalValue = isNaN(numValue) ? '' : numValue.toFixed(2);

    // ⚡ onChange už se volá při každém znaku, při blur jen formatujeme
    // Ale stále musíme zavolat parent onBlur pro validaci
    if (onBlur) {
      onBlur(fieldName, finalValue);
    }
  };

  return (
    <CurrencyInputWrapper>
      <InputWithIcon hasIcon>
        <Calculator />
        <Input
          ref={inputRef}
          type="text"
          name={fieldName}
          placeholder={placeholder}
          value={localValue}
          onChange={handleChange}
          onFocus={handleFocus}
          onBlur={handleBlurLocal}
          disabled={disabled}
          style={{ textAlign: 'right', paddingRight: '40px' }}
          hasError={hasError}
          hasIcon
        />
      </InputWithIcon>
      <CurrencySymbol disabled={disabled}>Kč</CurrencySymbol>
    </CurrencyInputWrapper>
  );
}

// DatePicker Component - prevzato z src/components/DatePicker.js
function DatePicker({ fieldName, value, onChange, onBlur, disabled, hasError, placeholder = 'Vyberte datum' }) {
  const [isOpen, setIsOpen] = useState(false);
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [openUpwards, setOpenUpwards] = useState(false); // 🎯 Detekce směru otevření
  const wrapperRef = useRef(null);
  const calendarRef = useRef(null);

  // Parse value to Date
  const selectedDate = value ? new Date(value) : null;

  // Update currentMonth when value changes to show correct month
  useEffect(() => {
    if (value) {
      const date = new Date(value);
      if (!isNaN(date.getTime())) {
        setCurrentMonth(date);
      }
    }
  }, [value]);

  // Close calendar when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen]);

  // 🎯 Detekce směru otevření kalendáře (nahoru/dolů) podle dostupného místa
  useEffect(() => {
    if (isOpen && wrapperRef.current) {
      const checkPosition = () => {
        if (!wrapperRef.current) return;

        const buttonRect = wrapperRef.current.getBoundingClientRect();
        const calendarHeight = 380; // Přibližná výška kalendáře
        const footerHeight = 54; // Výška fixní patičky
        const buffer = 20; // Extra buffer pro bezpečnost

        const spaceBelow = window.innerHeight - buttonRect.bottom - footerHeight - buffer;
        const spaceAbove = buttonRect.top - buffer;

        // Otevři nahoru pokud: není dost místa dole NEBO je nahoře výrazně více místa
        const shouldOpenUpward = spaceBelow < 300 || (spaceBelow < calendarHeight && spaceAbove > spaceBelow + 50);

        setOpenUpwards(shouldOpenUpward);
      };

      checkPosition();

      // Přidej scroll listener pro re-pozicování
      const scrollContainer = document.querySelector('[class*="ScrollableContent"]');
      if (scrollContainer) {
        scrollContainer.addEventListener('scroll', checkPosition);
        return () => scrollContainer.removeEventListener('scroll', checkPosition);
      }
    }
  }, [isOpen]);

  // Format date for display
  const formatDisplayDate = (date) => {
    if (!date) return '';
    try {
      const d = new Date(date);
      if (isNaN(d.getTime())) return ''; // Invalid date check
      return d.toLocaleDateString('cs-CZ', { day: '2-digit', month: '2-digit', year: 'numeric' });
    } catch (err) {
      return '';
    }
  };

  // Format date for input (YYYY-MM-DD)
  const formatInputDate = (date) => {
    const d = new Date(date);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  // Get calendar days for current month
  const getCalendarDays = () => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();

    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);

    const startDay = firstDay.getDay() === 0 ? 6 : firstDay.getDay() - 1; // Monday = 0
    const days = [];

    // Previous month days
    for (let i = startDay - 1; i >= 0; i--) {
      const date = new Date(year, month, -i);
      days.push({ date, isOtherMonth: true });
    }

    // Current month days
    for (let i = 1; i <= lastDay.getDate(); i++) {
      const date = new Date(year, month, i);
      days.push({ date, isOtherMonth: false });
    }

    // Next month days
    const remainingDays = 42 - days.length; // 6 rows * 7 days
    for (let i = 1; i <= remainingDays; i++) {
      const date = new Date(year, month + 1, i);
      days.push({ date, isOtherMonth: true });
    }

    return days;
  };

  const handleDateSelect = (date) => {
    const formattedDate = formatInputDate(date);
    // Volat onChange s hodnotou - fieldName je už v props
    onChange(formattedDate);
    if (onBlur) {
      onBlur(formattedDate);
    }
    setIsOpen(false);
  };

  const handleToday = (e) => {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    handleDateSelect(new Date());
  };

  const handleClear = (e) => {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    onChange('');
    if (onBlur) {
      onBlur('');
    }
    setIsOpen(false);
  };

  const prevMonth = (e) => {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1));
  };

  const nextMonth = (e) => {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1));
  };

  const today = new Date();
  const calendarDays = getCalendarDays();

  const displayText = value ? formatDisplayDate(value) : placeholder;

  return (
    <DatePickerWrapper ref={wrapperRef} data-field={fieldName}>
      <InputWithIcon hasIcon>
        <Calendar />
        <DateInputButton
          type="button"
          onClick={() => !disabled && setIsOpen(!isOpen)}
          disabled={disabled}
          hasError={hasError}
          hasValue={!!value}
          data-datepicker={fieldName}
        >
          {displayText}
        </DateInputButton>

        {/* Křížek pro smazání */}
        {value && !disabled && (
          <DateClearButton
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              handleClear(e);
            }}
            title="Smazat datum"
          >
            ✕
          </DateClearButton>
        )}

        {/* Tlačítko pro dnešní datum */}
        {!disabled && (
          <DateTodayButton
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              handleToday(e);
            }}
            title="Nastavit dnešní datum"
          >
            📅
          </DateTodayButton>
        )}
      </InputWithIcon>

      {isOpen && !disabled && (
        <DateCalendarPopup ref={calendarRef} openUpwards={openUpwards}>
          <CalendarHeader>
            <CalendarNav onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              prevMonth(e);
            }}>◀</CalendarNav>
            <CalendarTitle>
              <span>{currentMonth.toLocaleDateString('cs-CZ', { month: 'long' })}</span>
              <span>{currentMonth.getFullYear()}</span>
            </CalendarTitle>
            <CalendarNav onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              nextMonth(e);
            }}>▶</CalendarNav>
          </CalendarHeader>

          <CalendarGrid>
            <CalendarDay>Po</CalendarDay>
            <CalendarDay>Út</CalendarDay>
            <CalendarDay>St</CalendarDay>
            <CalendarDay>Čt</CalendarDay>
            <CalendarDay>Pá</CalendarDay>
            <CalendarDay>So</CalendarDay>
            <CalendarDay>Ne</CalendarDay>

            {calendarDays.map((day, index) => {
              const isToday = day.date.toDateString() === today.toDateString();
              const isSelected = selectedDate && day.date.toDateString() === selectedDate.toDateString();

              return (
                <CalendarDate
                  key={index}
                  onClick={(e) => {
                    e.stopPropagation();
                    handleDateSelect(day.date);
                  }}
                  isToday={isToday}
                  isSelected={isSelected}
                  isOtherMonth={day.isOtherMonth}
                >
                  {day.date.getDate()}
                </CalendarDate>
              );
            })}
          </CalendarGrid>

          <CalendarFooter>
            <CalendarButton
              className="today"
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                handleDateSelect(new Date());
              }}
            >
              Dnes
            </CalendarButton>
            <CalendarButton
              className="clear"
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                onChange('');
                if (onBlur) {
                  onBlur('');
                }
                setIsOpen(false);
              }}
            >
              Smazat
            </CalendarButton>
          </CalendarFooter>
        </DateCalendarPopup>
      )}
    </DatePickerWrapper>
  );
}

