/**
 * � VALIDACE STŘEDISEK: Fallback pro neaktivní střediska
 *
 * Zkontroluje, zda jsou všechna střediska aktivní.
 * Pokud ne, nahradí neaktivní střediska za "100" (Správa Kladno).
 *
 * @param {string[]} strediskaCodes - Array kódů středisek
 * @param {Array} strediskaOptions - Dostupná aktivní střediska
 * @returns {string[]} - Validovaný array středisek
 */
const validateAndFixStrediska = (strediskaCodes, strediskaOptions) => {
  if (!Array.isArray(strediskaCodes) || strediskaCodes.length === 0) {
    return strediskaCodes;
  }

  const FALLBACK_STREDISKO = "100"; // 100 Správa Kladno

  return strediskaCodes.map(kod => {
    // Zkontroluj, zda středisko existuje v aktivních
    const exists = strediskaOptions.find(opt =>
      (opt.value && opt.value === kod) ||
      (opt.kod && opt.kod === kod) ||
      (opt.kod_stavu && opt.kod_stavu === kod)
    );

    if (!exists) {
      return FALLBACK_STREDISKO;
    }

    return kod;
  });
};

/**
 * �🔄 CENTRÁLNÍ TRANSFORMACE: Backend → Frontend
 *
 * Transformuje data z backendu do formátu pro frontend form
 * Specifikace: DATA-FORMAT-CONTRACT.md
 *
 * @see src/utils/dataTransformHelpers.js
 * @param {object} backendData - Raw data z V2 API
 * @returns {object} - Transformovaná data pro formData
 *
 * Použití:
 * - Po INSERT/UPDATE objednávky (saveOrderToAPI)
 * - Po načtení objednávky (loadOrderData)
 * - Po jakékoli komunikaci s backendem
 */
const transformBackendDataToFrontend = (backendData) => {
  if (!backendData) return {};

  const transformed = { ...backendData };

  // 1. POLOŽKY: Backend vrací 'polozky', FE používá 'polozky_objednavky'
  if (backendData.polozky && !backendData.polozky_objednavky) {
    // 🔧 FIX: Normalizovat ceny z DB - zajistit že jsou ve formátu "12345.67" (string s tečkou, 2 des. místa)
    transformed.polozky_objednavky = Array.isArray(backendData.polozky) 
      ? backendData.polozky.map(item => {
          return {
            ...item,
            // 💰 LP na položce: zajistit number (jinak select po prvním SAVE může zobrazit jen ID)
            lp_id: item.lp_id !== undefined && item.lp_id !== null && String(item.lp_id).trim() !== ''
              ? parseInt(item.lp_id, 10)
              : (item.polozka_lp_id !== undefined && item.polozka_lp_id !== null && String(item.polozka_lp_id).trim() !== ''
                  ? parseInt(item.polozka_lp_id, 10)
                  : null),
            cena_bez_dph: typeof item.cena_bez_dph === 'number' 
              ? item.cena_bez_dph.toFixed(2) 
              : (parseFloat((item.cena_bez_dph || '0').toString().replace(/[^\d,.-]/g, '').replace(',', '.')) || 0).toFixed(2),
            cena_s_dph: typeof item.cena_s_dph === 'number' 
              ? item.cena_s_dph.toFixed(2) 
              : (parseFloat((item.cena_s_dph || '0').toString().replace(/[^\d,.-]/g, '').replace(',', '.')) || 0).toFixed(2),
            sazba_dph: item.sazba_dph !== undefined && item.sazba_dph !== null ? parseInt(item.sazba_dph) : 21,
            poznamka: item.poznamka || ''  // ✅ Backend vrací poznamka přímo jako plain text
          };
        })
      : [];
    delete transformed.polozky; // Vyčistit BE pole
  }

  // 🔧 LP na položce: sjednotit typ `lp_id` na number i pokud backend vrátí `polozky_objednavky` přímo
  if (Array.isArray(transformed.polozky_objednavky) && transformed.polozky_objednavky.length > 0) {
    transformed.polozky_objednavky = transformed.polozky_objednavky.map(item => {
      const raw = item?.lp_id ?? item?.polozka_lp_id;
      const lp_id = raw !== undefined && raw !== null && String(raw).trim() !== '' ? parseInt(raw, 10) : null;
      return {
        ...item,
        lp_id
      };
    });
  }

  // 2. ✅ STŘEDISKA: Normalizovat do array stringů
  if (backendData.strediska_kod) {
    transformed.strediska_kod = normalizeStrediskaFromBackend(backendData.strediska_kod);
  }

  // 3. ✅ FINANCOVÁNÍ: Normalizovat do flat struktury (POUZE LP a SMLOUVA pole)
  
  if (backendData.financovani) {
    
    const financing = normalizeFinancovaniFromBackend(backendData.financovani);
    
    
    Object.assign(transformed, financing);
  } else {
  }

  // 3.5. ✅ VŠECHNA POLE (LP, SMLOUVA, INDIVIDUÁLNÍ, POJISTNÁ UDÁLOST) se načítají z financovani objektu
  // normalizeFinancovaniFromBackend() už to udělal v kroku 3

  // 4. ČÍSLOVÁNÍ: cislo_objednavky → ev_cislo
  if (backendData.cislo_objednavky && !backendData.ev_cislo) {
    transformed.ev_cislo = backendData.cislo_objednavky;
  }

  // 5. ✅ WORKFLOW: Parsovat stav_workflow_kod z JSON stringu na array
  // Backend vrací: '["NOVA","SCHVALENA"]' → FE očekává: ["NOVA","SCHVALENA"]
  if (backendData.stav_workflow_kod) {
    if (typeof backendData.stav_workflow_kod === 'string' && backendData.stav_workflow_kod.trim().startsWith('[')) {
      try {
        const parsed = JSON.parse(backendData.stav_workflow_kod);
        if (Array.isArray(parsed)) {
          transformed.stav_workflow_kod = parsed;
        }
      } catch (e) {
        // Zachovat původní hodnotu
      }
    }
    // Pokud už je array nebo není JSON string, zachovat původní hodnotu
  }

  // 5.5. ✅ DOKONČENÍ: Zajistit správné parsování potvrzeni_dokonceni_objednavky
  // Backend vrací číslo (0/1), FE očekává integer
  if (backendData.potvrzeni_dokonceni_objednavky !== undefined) {
    transformed.potvrzeni_dokonceni_objednavky = parseInt(backendData.potvrzeni_dokonceni_objednavky, 10) || 0;
  }

  // 5.6. ✅ STAV ODESLÁNÍ: Parsovat boolean/integer fieldy pro odeslání a storno
  // Backend může vracet 0/1 nebo true/false
  if (backendData.stav_odeslano !== undefined) {
    transformed.stav_odeslano = Boolean(backendData.stav_odeslano);
  }
  // ℹ️ `stav_stornovano` není DB sloupec.
  // Je to UI helper pro checkbox a odvozuje se z workflow (ZRUSENA).

  // ℹ️  INDIVIDUÁLNÍ SCHVÁLENÍ a POJISTNÁ UDÁLOST: Načítají se z root objektu (krok 3.5)
  //     stejně jako cislo_smlouvy - NEJSOU vnořené ve financovani objektu

  // 5.8. ✅ DATUMY A TEXTOVÉ FIELDY: Kopírovat přímo bez transformace
  const directCopyFields = [
    'odeslani_storno_duvod',
    'identifikator',
    'dt_odeslani'
    // 🛑 NEEXISTUJÍ v DB: storno_provedl, stav_stornovano (UI helper)
  ];

  // 🛑 VYČISTIT DEPRECATED POLE (pokud jsou v localStorage draftu nebo starých datech)
  // Pozn.: `stav_stornovano` nemažeme - používá se v UI.
  const deprecatedFields = ['storno_provedl', 'storno_uzivatel_id'];
  deprecatedFields.forEach(field => {
    if (backendData[field] !== undefined) {
      delete transformed[field]; // Odstranit z výstupu
    }
  });

  directCopyFields.forEach(field => {
    if (backendData[field] !== undefined) {
      transformed[field] = backendData[field];
    }
  });

  // 5.9. ✅ STORNO UI HELPER: odvodit z workflow (ZRUSENA)
  const workflowForStornoDetection = transformed.stav_workflow_kod ?? backendData.stav_workflow_kod;
  const isZrusenaByWorkflow = (() => {
    try {
      const wf = workflowForStornoDetection;
      let states = [];

      if (Array.isArray(wf)) {
        states = wf;
      } else if (typeof wf === 'string') {
        const trimmed = wf.trim();
        if (!trimmed) return false;

        // JSON array string
        if (trimmed.startsWith('[')) {
          const parsed = JSON.parse(trimmed);
          states = Array.isArray(parsed) ? parsed : [];
        } else {
          // Fallback: starý formát "A,B,C"
          states = trimmed.split(',').map(s => s.trim()).filter(Boolean);
        }
      } else {
        states = [];
      }

      return Array.isArray(states) && states.includes('ZRUSENA');
    } catch (e) {
      return false;
    }
  })();
  transformed.stav_stornovano = Boolean(isZrusenaByWorkflow);

  // ✅ Jednotné datum pro odeslání i storno: pokud backend má dt_odeslani, naplň datum_odeslani
  // (UI DatePicker používá vždy datum_odeslani)
  if (backendData.dt_odeslani && (!transformed.datum_odeslani || String(transformed.datum_odeslani).trim() === '')) {
    transformed.datum_odeslani = String(backendData.dt_odeslani).split(' ')[0];
  }

  // Mutual exclusive checkboxy: pokud je storno, „Odesláno“ musí být vypnuté
  if (transformed.stav_stornovano) {
    transformed.stav_odeslano = false;
  }

  // 6. POZNÁMKA: Backend vrací 'poznamka', FE používá 'poznamka_objednavky'
  if (backendData.poznamka) {
    // Pokud je poznámka JSON string (chyba z Notes panelu), zkus parsovat text
    let poznamkaText = backendData.poznamka;

    // Opakovaně parsuj, dokud je to JSON (řeší vícenásobné zanořování)
    let maxIterations = 5; // Ochrana proti nekonečné smyčce
    while (typeof poznamkaText === 'string' && poznamkaText.trim().startsWith('{') && maxIterations > 0) {
      try {
        const parsed = JSON.parse(poznamkaText);

        // Pokud má strukturu {text, datum, typ} z Notes panelu, extrahuj text
        if (parsed.text !== undefined) {
          poznamkaText = parsed.text;
        } else {
          // Jiná JSON struktura - zachovej původní
          break;
        }
      } catch (e) {
        // Není validní JSON - konec parsování
        break;
      }
      maxIterations--;
    }

    transformed.poznamka_objednavky = poznamkaText;
    delete transformed.poznamka; // Vyčistit BE pole
  }

  // 7. ✅ POTVRZENÍ DODAVATELEM: Parsovat JSON string z DB
  // Backend vrací: '{"potvrzeni":"ANO","zpusoby":["podepsana_objednavka"],"platba":"faktura"}'
  // FE očekává: {potvrzeni: 'ANO', zpusoby: ['podepsana_objednavka'], platba: 'faktura'}
  if (backendData.dodavatel_zpusob_potvrzeni && typeof backendData.dodavatel_zpusob_potvrzeni === 'string') {
    try {
      const parsed = JSON.parse(backendData.dodavatel_zpusob_potvrzeni);
      transformed.dodavatel_zpusob_potvrzeni = parsed;
    } catch (e) {
      // Zachovat původní hodnotu při chybě
    }
  }

  return transformed;
};

/**
 * Helper funkce pro zobrazení LP kódu s rokem
 * Přidává zkrácený rok k číslu LP: LPIT1 → LPIT1'25 (pro rok 2025)
 * @param {string} cisloLp - Číslo LP (např. "LPIT1")
 * @param {string|Date} platneDo - Datum platnosti do
 * @returns {string} - Číslo LP s rokem (např. "LPIT1'25")
 */
const formatLpWithYear = (cisloLp, platneDo) => {
  if (!cisloLp) return '';
  if (!platneDo) return cisloLp;
  
  try {
    const date = typeof platneDo === 'string' ? new Date(platneDo) : platneDo;
    const year = date.getFullYear();
    const shortYear = year.toString().slice(-2); // Poslední 2 číslice roku
    return `${cisloLp}'${shortYear}`;
  } catch (e) {
    return cisloLp; // Fallback při chybě
  }
};

