  // Fallback při chybě je řešen přímo v useDictionaries reducer

  /**
   * 🔄 Automatické doplnění dodavatele ze smlouvy
   * Použití: Při načtení objednávky ve fázi 3+ s financováním "Smlouva"
   * Priorita: 1) Lokální adresář, 2) ARES, 3) Data ze smlouvy
   * @param {Object} orderData - Data objednávky s cislo_smlouvy a zpusob_financovani
   * @param {number} currentPhase - Aktuální fáze objednávky
   * @returns {Object|null} - Dodavatelská data nebo null
   */
  const autoFillSupplierFromContract = useCallback(async (orderData, currentPhase) => {
    try {
      // 1️⃣ KONTROLA PODMÍNEK
      // Spustit POUZE když:
      // - Objednávka je SCHVÁLENÁ (ale ještě není ODESLANÁ) - stav po schválení
      // - NEBO je rozpracovaná s financováním Smlouva
      const workflowStates = orderData.stav_workflow_kod ? 
        (typeof orderData.stav_workflow_kod === 'string' ? JSON.parse(orderData.stav_workflow_kod) : orderData.stav_workflow_kod) : [];
      
      const hasSchvalena = Array.isArray(workflowStates) && workflowStates.includes('SCHVALENA');
      const hasOdeslana = Array.isArray(workflowStates) && workflowStates.includes('ODESLANA');
      
      // NEPOUŽÍVAT pro objednávky co jsou už ODESLANÉ (tam musí být dodavatel vyplněný)
      if (hasOdeslana) {
        return null;
      }
      
      // Musí být buď SCHVÁLENÁ nebo rozpracovaná s financováním Smlouva
      const isSmlouvaFinancing = orderData.zpusob_financovani?.toLowerCase().includes('smlouva');
      if (!hasSchvalena && !isSmlouvaFinancing) {
        return null;
      }
      
      if (!isSmlouvaFinancing) {
        return null;
      }

      const hasSupplier = orderData.dodavatel_nazev?.trim() || orderData.dodavatel_ico?.trim();
      if (hasSupplier) {
        return null; // Už je vyplněný - buď z DB nebo z draftu
      }

      const cisloSmlouvy = orderData.cislo_smlouvy?.trim();
      if (!cisloSmlouvy) {
        return null;
      }
      
      // 2️⃣ NAČÍST SEZNAM SMLUV PŘÍMO (eliminace závislosti na state)
      let currentSmlouvyList = [];
      try {
        const response = await getSmlouvyList({
          token,
          username,
          show_inactive: false,
          limit: 500,
          pouzit_v_obj_formu: true
        });
        
        if (response?.data && Array.isArray(response.data)) {
          currentSmlouvyList = response.data;
        }
      } catch (loadError) {
        return null;
      }

      // 3️⃣ NAJÍT SMLOUVU V SEZNAMU
      const smlouva = currentSmlouvyList.find(s => 
        s.cislo_smlouvy === cisloSmlouvy || 
        s.evidencni_cislo === cisloSmlouvy
      );

      if (!smlouva) {
        return null;
      }

      const icoZeSmlouvy = smlouva.ico?.trim();
      if (!icoZeSmlouvy || icoZeSmlouvy.length < 8) {
        // Smlouva nemá IČO nebo je neplatné - vrátíme jen název
        return {
          dodavatel_nazev: smlouva.nazev_firmy || '',
          dodavatel_ico: '',
          source: 'smlouva-fallback'
        };
      }

      // 4️⃣ HLEDAT V LOKÁLNÍM ADRESÁŘI (primární zdroj)
      try {
        const localResult = await searchSupplierByIco({
          token: token,
          username: username,
          ico: icoZeSmlouvy
        });

        if (localResult?.data && Array.isArray(localResult.data) && localResult.data.length > 0) {
          const supplier = localResult.data[0];
          return {
            dodavatel_nazev: supplier.nazev || supplier.name || smlouva.nazev_firmy || '',
            dodavatel_adresa: supplier.adresa || supplier.address || '',
            dodavatel_ico: supplier.ico || icoZeSmlouvy,
            dodavatel_dic: supplier.dic || '',
            dodavatel_zastoupeny: supplier.zastoupeny || supplier.represented || '',
            dodavatel_kontakt_jmeno: supplier.kontakt_jmeno || '',
            dodavatel_kontakt_email: supplier.kontakt_email || supplier.email || '',
            dodavatel_kontakt_telefon: supplier.kontakt_telefon || supplier.telefon || '',
            source: 'local'
          };
        }
      } catch (localError) {
        // Error in local directory search
      }

      // 5️⃣ FALLBACK NA ARES
      try {
        const aresUrl = `https://ares.gov.cz/ekonomicke-subjekty-v-be/rest/ekonomicke-subjekty/${icoZeSmlouvy}`;
        const aresResponse = await fetch(aresUrl, {
          method: 'GET',
          headers: { 'Accept': 'application/json' }
        });

        if (aresResponse.ok) {
          const aresData = await aresResponse.json();
          return {
            dodavatel_nazev: aresData.obchodniJmeno || smlouva.nazev_firmy || '',
            dodavatel_adresa: aresData.sidlo?.textovaAdresa || '',
            dodavatel_ico: aresData.ico || icoZeSmlouvy,
            dodavatel_dic: aresData.dic || '',
            dodavatel_zastoupeny: '',
            dodavatel_kontakt_jmeno: '',
            dodavatel_kontakt_email: '',
            dodavatel_kontakt_telefon: '',
            source: 'ares'
          };
        }
      } catch (aresError) {
        // Error in ARES query
      }

      // 6️⃣ FALLBACK NA DATA ZE SMLOUVY (pouze název a IČO)
      return {
        dodavatel_nazev: smlouva.nazev_firmy || '',
        dodavatel_ico: icoZeSmlouvy,
        source: 'smlouva'
      };

    } catch (error) {
      return null;
    }
  }, [token, username]);

  // 🔧 FIX: Callback funkce pro useFormController - definované až po všech state proměnných
  const handleDataLoaded = useCallback(async (loadedData, sourceOrderId) => {
      // Callback když jsou data načtena z DB
      // KRITICKÉ: Nastavit formData s načtenými daty

      // �️ OCHRANA: Zabránit opakovanému volání onDataLoaded PRO STEJNOU objednávku
      // ✅ FIX: Kontroluj současný editOrderId, ne jen flag
      const currentEditId = editOrderId || loadedData?.id || 'NEW';
      
      if (onDataLoadedCalledRef.current === currentEditId) {
        return;
      }

      // KRITICKÉ: Nastavit ochranu PŘED jakýmikoliv async operacemi
      onDataLoadedCalledRef.current = currentEditId;

      // 🛡️ DALŠÍ OCHRANA: Reset ochrany po 5 sekundách pro případ že by došlo k chybě
      setTimeout(() => {
        if (onDataLoadedCalledRef.current === currentEditId) {
          onDataLoadedCalledRef.current = null;
        }
      }, 5000);

      // ✅ FIX: Pro NOVOU objednávku okamžitě povolit autosave
      // Není potřeba čekat na draft loading - form je ready hned
      const isNewOrder = !editOrderId;
      if (isNewOrder) {
        setIsDraftLoaded(true); // ✅ Povolit autosave OKAMŽITĚ pro nové objednávky
        setIsInitialized(true); // ✅ Označit jako inicializovaný aby se nespustil duplicitní effect
      }

      // NOTE: sourceOrderIdForUnlock removed - formData.id is used directly
      // NOTE: formData.id removed - formData.id is single source of truth

      // Nastavit edit mode pokud má loadedData ID
      if (loadedData?.id) {
        setIsEditMode(true);
        // 🎯 PERSISTENCE: Ulož editOrderId do draftManager pro refresh
        draftManager.saveMetadata({ editOrderId: String(loadedData.id) });
      }

      // 🎯 NEBO pokud je editOrderId v URL - OKAMŽITĚ nastavit editMode
      if (editOrderId) {
        setIsEditMode(true);
        // 🎯 PERSISTENCE: Ulož editOrderId do draftManager pro refresh
        draftManager.saveMetadata({ editOrderId: String(editOrderId) });
      }

      // 🔥 NOVÉ: Načti draft PŘÍMO TADY během inicializace!
      let finalData = loadedData || {};
      const hasDbData = loadedData && Object.keys(loadedData).length > 0;

      if (user_id) {
        try {
          draftManager.setCurrentUser(user_id);
          const hasDraft = await draftManager.hasDraft();

          if (hasDraft) {
            const draftData = await draftManager.loadDraft();

            if (draftData?.formData) {
              // 🎯 KONTROLA: Patří draft k této objednávce?
              const draftOrderId = draftData.formData.id || draftData.formData?.id;
              const currentOrderId = editOrderId || loadedData?.id;

              // 💰 LP ČERPÁNÍ: Načíst z draftu pokud existuje
              if (draftData.fakturyLPCerpani && typeof draftData.fakturyLPCerpani === 'object') {
                setFakturyLPCerpani(draftData.fakturyLPCerpani);
              }

              // 🎯 Pokud draft má ID objednávky, JE TO EDITACE - nastav HNED!
              if (draftOrderId) {
                setIsEditMode(true);
                // NOTE: formData.id removed - formData.id is single source of truth
                // 🎯 PERSISTENCE: Ulož do draftManager pro refresh
                draftManager.saveMetadata({ editOrderId: String(draftOrderId) });
              }

              // ❌ Pokud je draft od JINÉ objednávky, IGNORUJ ho!
              if (currentOrderId && draftOrderId && String(draftOrderId) !== String(currentOrderId)) {
                // NEPOUŽÍVAT tento draft - patří k jiné objednávce
                console.warn('⚠️ Draft patří k jiné objednávce, ignoruji:', { draftOrderId, currentOrderId });
              } else if (hasDbData) {
                // ✅ Draft patří k TÉTO objednávce - použij ho!
                // 🎯 NOVÁ LOGIKA: LocalStorage VŽDY má prioritu (obsahuje aktuální změny uživatele)
                // DB slouží jen jako základ pro systémová/immutable pole

                finalData = {
                  ...loadedData, // Nejdřív DB (základní systémová data)
                  ...draftData.formData, // Pak LS draft PŘEPÍŠE všechny user-editable fieldy
                  
                  // ⚠️ IMMUTABLE systémová pole - VŽDY Z DB (nelze měnit)
                  id: loadedData.id,
                  ev_cislo: loadedData.ev_cislo || loadedData.cislo_objednavky,
                  cislo_objednavky: loadedData.cislo_objednavky,
                  datum_vytvoreni: loadedData.datum_vytvoreni,
                  datum_posledni_zmeny: loadedData.datum_posledni_zmeny,
                  
                  // ✅ FAKTURY: Preferovat draft faktury (obsahují lokální změny), fallback na DB
                  faktury: (draftData.formData.faktury && draftData.formData.faktury.length > 0) 
                    ? draftData.formData.faktury 
                    : (loadedData.faktury || [])
                };
              } else {
                // NEW: Použij draft
                finalData = draftData.formData;
              }
            }
          }
        } catch (error) {
          console.error('❌ Chyba při načítání draftu:', error);
        }
      }

      // 🔢 KRITICKÉ: SYNCHRONNÍ NAČTENÍ EV_CISLO pro nové objednávky
      // Priorita: Načíst číslo PŘED nastavením formData, ne asynchronně v useEffect
      if (isNewOrder && !finalData.ev_cislo && token && username) {
        try {
          const orderNumberData = await getNextOrderNumberV2(token, username);
          const nextNumber = orderNumberData.next_order_string || orderNumberData.order_number_string || orderNumberData.next_number;
          
          if (nextNumber) {
            finalData.ev_cislo = nextNumber;
            
            // Označit že ev_cislo je načteno aby useEffect ho už nenačítal
            if (window.__orderForm_hasLoadedNextNumberRef) {
              window.__orderForm_hasLoadedNextNumberRef.current = true;
            }
          } else {
            console.warn('⚠️ [OrderForm25/handleDataLoaded] API nevrátilo ev_cislo');
          }
        } catch (error) {
          console.error('❌ [OrderForm25/handleDataLoaded] Chyba při načítání ev_cislo:', error);
          // Fallback - useEffect to zkusí načíst
        }
      }

      // 🎯 NOVÁ OBJEDNÁVKA: Aplikovat výchozí hodnoty garanta a příkazce z user settings
      if (isNewOrder && user_id && !finalData.garant_uzivatel_id && !finalData.prikazce_id) {
        try {
          const { loadSettingsFromLocalStorage } = require('../services/userSettingsApi');
          const userSettings = loadSettingsFromLocalStorage(parseInt(user_id, 10));
          
          if (userSettings) {
            // Extrahuj hodnoty garanta
            if (userSettings.vychozi_garant_id && userSettings.vychozi_garant_id !== '' && userSettings.vychozi_garant_id !== null) {
              const defaultGarantId = typeof userSettings.vychozi_garant_id === 'object' 
                ? userSettings.vychozi_garant_id.value 
                : userSettings.vychozi_garant_id;
              
              if (defaultGarantId && defaultGarantId !== '') {
                finalData.garant_uzivatel_id = String(defaultGarantId);
              }
            }
            
            // Extrahuj hodnoty příkazce
            if (userSettings.vychozi_prikazce_id && userSettings.vychozi_prikazce_id !== '' && userSettings.vychozi_prikazce_id !== null) {
              const defaultPrikazceId = typeof userSettings.vychozi_prikazce_id === 'object'
                ? userSettings.vychozi_prikazce_id.value
                : userSettings.vychozi_prikazce_id;
              
              if (defaultPrikazceId && defaultPrikazceId !== '') {
                finalData.prikazce_id = String(defaultPrikazceId);
              }
            }
          } else {
          }
        } catch (error) {
          console.error('❌ [OrderForm25/handleDataLoaded] Chyba při načítání výchozích hodnot garanta/příkazce:', error);
        }
      }

      // 🔄 AUTOMATICKÉ DOPLNĚNÍ DODAVATELE ZE SMLOUVY
      // Pokud je fáze 3+, financování = Smlouva a dodavatel prázdný, zkusit doplnit
      let wasAutoFilled = false;
      if (Object.keys(finalData).length > 0) {
        const currentPhase = getWorkflowPhase(finalData.stav_workflow_kod);
        
        try {
          const supplierFromContract = await autoFillSupplierFromContract(finalData, currentPhase);
          
          if (supplierFromContract) {
            // Sloučit dodavatelská data do finalData
            finalData = {
              ...finalData,
              ...supplierFromContract
            };
            
            // Nastavit zdroj pro zobrazení v labelu
            setSupplierAutoFillSource(supplierFromContract.source);
            
            wasAutoFilled = true;
          }
        } catch (error) {
        }
      }

      // Nastavit finální data (pokud není prázdné)
      if (Object.keys(finalData).length > 0) {
        setFormData(finalData);

        // 🐛 DEBUG: Log workflow stav při otevření objednávky O-0151
        if (finalData?.cislo_objednavky && String(finalData.cislo_objednavky).includes('O-0151')) {
          console.log('🧾 [OrderForm25] O-0151 loaded', {
            cislo_objednavky: finalData.cislo_objednavky,
            stav_objednavky: finalData.stav_objednavky,
            stav_workflow_kod: finalData.stav_workflow_kod,
            parsed_workflow: parseWorkflowStates(finalData.stav_workflow_kod)
          });
        }

        // 🎯 EXTRAHOVAT LP OPTIONS z enriched order response
        // LP options jsou v loadedData.financovani.lp_nazvy (ne v lp_options!)
        
        // Extrahuj LP z financovani.lp_nazvy (primární zdroj pro položky)
        if (loadedData?.financovani?.lp_nazvy && Array.isArray(loadedData.financovani.lp_nazvy)) {
          const lpOptions = loadedData.financovani.lp_nazvy
            .map(lp => {
              const lpKodWithYear = formatLpWithYear(lp.cislo_lp || lp.kod, lp.platne_do);
              return {
                id: lp.id,
                kod: lp.cislo_lp || lp.kod || `LP${lp.id}`,
                nazev: lp.nazev || 'Bez názvu',
                kategorie: lp.kategorie,
                limit: lp.limit || lp.celkovy_limit,
                cerpano: lp.cerpano || lp.skutecne_cerpano,
                zbyva: lp.zbyva || lp.zbyva_skutecne,
                rok: lp.rok,
                platne_od: lp.platne_od,
                platne_do: lp.platne_do,
                label: `${lpKodWithYear} - ${lp.nazev || 'Bez názvu'}`
              };
            })
            .sort((a, b) => a.nazev.localeCompare(b.nazev, 'cs'));
          
          setLpOptionsForItems(lpOptions);
        } else if (finalData.lp_kod && Array.isArray(finalData.lp_kod) && finalData.lp_kod.length > 0) {
          // ✅ FALLBACK: Objednávka má LP financování, ale chybí lp_nazvy data - načti z API
          
          try {
            // 🔧 KROK 1: Pokud lpKodyOptions není dostupné, načti všechny LP
            let lpMappingData = lpKodyOptions || [];
            if (!lpKodyOptions || lpKodyOptions.length === 0) {
              try {
                lpMappingData = await fetchLimitovanePrisliby({ token, username });
              } catch (err) {
                console.error('❌ Chyba načítání LP mapování:', err);
                lpMappingData = [];
              }
            }
            
            // 🔧 KROK 2: Načti detaily pro každé LP (převeď ID → KÓD)
            const lpDetails = await Promise.all(
              finalData.lp_kod.map(async (lpValue) => {
                // Deklarujeme proměnné na úrovni map callbacku, aby byly dostupné i v catch
                let lpKod = lpValue;
                const originalValue = lpValue;
                
                try {
                  // 🔧 lpValue může být ID (number/string-number) nebo KÓD (string)
                  // Pokud je to číslo, najdi KÓD z lpMappingData, jinak použij přímo
                  
                  if (lpMappingData && lpMappingData.length > 0) {
                    // Zkus najít podle ID nebo KÓD
                    const lpOption = lpMappingData.find(opt => 
                      opt.id === lpValue || 
                      opt.id === Number(lpValue) ||
                      opt.kod === lpValue ||
                      opt.cislo_lp === lpValue
                    );
                    
                    if (lpOption) {
                      lpKod = lpOption.cislo_lp || lpOption.kod || lpValue;
                    } else {
                      console.warn(`⚠️ LP ${lpValue} nebylo nalezeno v LP mapování (${lpMappingData.length} záznamů)`);
                      // Zkusíme použít hodnotu přímo - možná je to už KÓD
                    }
                  } else {
                    console.warn('⚠️ LP mapování není dostupné, zkusím hodnotu přímo:', lpValue);
                  }
                  
                  const lpDetail = await fetchLPDetail({ token, username, cislo_lp: lpKod });
                  // ✅ Zkontroluj, jestli API vrátilo platná data
                  if (!lpDetail || !lpDetail.id) {
                    console.warn(`⚠️ LP ${lpKod} (ID: ${originalValue}) nebylo nalezeno nebo nemá platná data`);
                    return null;
                  }
                  const lpKodWithYear = formatLpWithYear(lpDetail.cislo_lp || lpDetail.kod, lpDetail.platne_do);
                  return {
                    id: lpDetail.id,
                    kod: lpDetail.cislo_lp || lpDetail.kod || `LP${lpDetail.id}`,
                    nazev: lpDetail.nazev_uctu || lpDetail.nazev || 'Bez názvu',
                    kategorie: lpDetail.kategorie,
                    limit: lpDetail.celkovy_limit || 0,
                    cerpano: lpDetail.skutecne_cerpano || 0,
                    zbyva: lpDetail.zbyva_skutecne || 0,
                    rok: lpDetail.rok,
                    platne_od: lpDetail.platne_od,
                    platne_do: lpDetail.platne_do,
                    label: `${lpKodWithYear} - ${lpDetail.nazev_uctu || lpDetail.nazev || 'Bez názvu'}`
                  };
                } catch (err) {
                  console.error(`❌ Chyba načítání LP ${lpKod} (ID: ${originalValue}):`, err);
                  return null;
                }
              })
            );
            const validLpOptions = lpDetails.filter(lp => lp !== null).sort((a, b) => a.nazev.localeCompare(b.nazev, 'cs'));
            setLpOptionsForItems(validLpOptions);
          } catch (err) {
            console.error('❌ Chyba při načítání LP z API:', err);
            setLpOptionsForItems([]);
          }
        } else {
          // Není LP financování
          setLpOptionsForItems([]);
        }

        // 📸 ULOŽIT SNAPSHOT původního stavu pro detekci změn
        if (finalData.id) {
          originalFormDataRef.current = JSON.parse(JSON.stringify(finalData));
        }

        // 💾 ULOŽIT DRAFT po autoFill (aby se změny zachovaly při F5)
        if (wasAutoFilled && editOrderId && draftManager) {
          try {
            draftManager.setCurrentUser(user_id);
            await draftManager.saveDraft(finalData, {
              orderId: parseInt(editOrderId)
            });
          } catch (draftError) {
            // Nepodařilo se uložit draft
          }
        }

        // ✅ KRITICKÉ: Pokud má ev_cislo, nastavit ref aby se už neptalo na next-number!
        if (finalData.ev_cislo && finalData.ev_cislo !== 'Načítám...') {
          if (window.__orderForm_hasLoadedNextNumberRef) {
            window.__orderForm_hasLoadedNextNumberRef.current = true;
          }
        }

        // ✅ Nastavit isInitialized flag aby se zabránilo duplicitnímu načítání
        setIsInitialized(true);
      }

      // ✅ Pro EDIT mode: Označit že inicializace je hotová až tady (po načtení draftu)
      // Pro NEW order už je isDraftLoaded=true nastaveno výše
      if (!isNewOrder) {
        if (process.env.NODE_ENV === 'development') {
        }
        setIsDraftLoaded(true);
        
        // ✅ KRITICKÉ: Povolit autosave i pro EDIT mode!
        draftManager.setAutosaveEnabled(true, 'EDIT order initialization');
        
        // 🔥 KRITICKÉ: Poslat broadcast MenuBaru - EDIT MODE JE READY!
        broadcastOrderState({
          isEditMode: true,
          isNewOrder: false,
          orderId: finalData.id || editOrderId,
          orderNumber: finalData.cislo_objednavky || finalData.ev_cislo || ''
        });
      }
  }, [editOrderId, user_id, draftManager, setFormData, setIsEditMode, setIsDraftLoaded, setIsInitialized, autoFillSupplierFromContract, setSupplierAutoFillSource, broadcastOrderState]);

  // 🎨 HELPER FUNKCE PRO FORMÁTOVANÉ TOASTY
  // Vytváří jednotný vzhled pro všechny toast zprávy s ikonami a barvami
  const formatToastMessage = useCallback((message, type = 'info') => {
    const styles = {
      error: {
        bg: '#fff1f0',
        color: '#d32f2f',
        icon: <AlertCircle size={18} color="#ff4d4f" />,
      },
      success: {
        bg: '#f0f9ff',
        color: '#0d7d3e',
        icon: <CheckCircle2 size={18} color="#10b981" />,
      },
      warning: {
        bg: '#fff7e6',
        color: '#d46b08',
        icon: <AlertTriangle size={18} color="#f59e0b" />,
      },
      info: {
        bg: '#f5f5f5',
        color: '#4b5563',
        icon: <InfoIcon size={18} color="#6b7280" />,
      }
    };

    const style = styles[type] || styles.info;

    return (
      <div style={{ 
        display: 'flex', 
        alignItems: 'flex-start', 
        gap: '10px',
        padding: '4px',
        fontFamily: 'system-ui, -apple-system, sans-serif'
      }}>
        <div style={{ flexShrink: 0, marginTop: '2px' }}>
          {style.icon}
        </div>
        <div style={{ 
          flex: 1,
          fontSize: '14px',
          lineHeight: '1.5',
          color: style.color
        }}>
          {message}
        </div>
      </div>
    );
  }, []);

  // Ostatní callback funkce pro formController
  const handleError = useCallback((error) => {
    // Callback při chybě inicializace
    showToast?.(formatToastMessage(`Nepodařilo se načíst formulář: ${error.message}`, 'error'), { type: 'error' });
  }, [formatToastMessage]); // 🔧 FIX: Remove showToast dependency to prevent infinite loop

  const handleReady = useCallback(() => {
    // Formulář ready - můžeme dodatečně inicializovat UI

    // 🚫 ZRUŠENO: Auto-scroll po načtení formuláře (na žádost uživatele)
  }, []);

  // 🔧 FIX: Reset onDataLoadedCalledRef když se mění editOrderId
  // Zajistí, že při navigaci mezi objednávkami se data správně načtou
  useEffect(() => {
    onDataLoadedCalledRef.current = null;
  }, [editOrderId]);

  // Tento hook řídí celou inicializaci formuláře a eliminuje race conditions
  const formController = useFormController({
    token,
    username,
    userId: user_id,
    editOrderId,
    archivovanoParam,
    onDataLoaded: handleDataLoaded,
    onError: handleError,
    onReady: handleReady
  });

  // Rozbalení formController pro snadnější přístup
  const { lifecycle, dictionaries, orderDataLoader, ui } = formController;

  // ✅ REFACTORED: Číselníky a jejich loading states nyní z formController
  // Aliasy pro zachování zpětné kompatibility se stávajícím kódem
  const allUsers = dictionaries.data?.allUsers || [];
  const approversBase = dictionaries.data?.approvers || [];
  const strediskaOptions = dictionaries.data?.strediskaOptions || [];
  const financovaniOptions = dictionaries.data?.financovaniOptions || [];
  const druhyObjednavkyOptions = dictionaries.data?.druhyObjednavkyOptions || [];
  const druhyObjednavkyRawData = dictionaries.data?.druhyObjednavkyRawData || null;
  const lpKodyOptions = dictionaries.data?.lpKodyOptions || [];
  const prilohyTypyOptions = dictionaries.data?.prilohyTypyOptions || [];
  const typyFakturOptions = dictionaries.data?.typyFakturOptions || []; // Typy faktur z reduceru
  const stavyWorkflowMap = dictionaries.data?.stavyWorkflowMap || {}; // 🆕 Mapa workflow stavů z DB číselníku

  // 💰 Helper: Vytvořit LP řádky s 0 Kč z vybraných LP kódů (pro faktury 0 Kč)
  const buildZeroLpRowsFromSelection = React.useCallback((selectedLpValues) => {
    if (!Array.isArray(selectedLpValues) || selectedLpValues.length === 0) return [];

    const resolveLpRef = (value) => {
      let lp_id = null;
      let lp_cislo = '';

      if (value && typeof value === 'object') {
        lp_id = value.id ?? value.lp_id ?? null;
        lp_cislo = value.cislo_lp || value.kod || value.lp_cislo || '';

        if (!lp_cislo && lp_id !== null && lp_id !== undefined) {
          const opt = lpKodyOptions.find(o => String(o.id) === String(lp_id));
          lp_cislo = opt?.cislo_lp || opt?.kod || '';
        }
      } else {
        const raw = String(value ?? '').trim();
        if (raw) {
          if (/^\d+$/.test(raw)) {
            lp_id = parseInt(raw, 10);
            const opt = lpKodyOptions.find(o => String(o.id) === raw);
            lp_cislo = opt?.cislo_lp || opt?.kod || '';
          } else {
            lp_cislo = raw;
            const opt = lpKodyOptions.find(o => String(o.kod) === raw || String(o.cislo_lp) === raw);
            lp_id = opt?.id ?? null;
          }
        }
      }

      return {
        lp_id: lp_id ?? null,
        lp_cislo: String(lp_cislo || '').trim()
      };
    };

    return selectedLpValues
      .map((value, index) => {
        const { lp_id, lp_cislo } = resolveLpRef(value);
        if (!lp_id && !lp_cislo) return null;

        return {
          id: `auto-lp-${index}`,
          lp_id,
          lp_cislo,
          castka: 0,
          poznamka: ''
        };
      })
      .filter(Boolean);
  }, [lpKodyOptions]);

  // 🆕 Memoizovaná hodnota: Je druh objednávky majetek (atribut_objektu = 1)?
  const isMaterialOrder = React.useMemo(() => {
    if (!formData.druh_objednavky_kod) return false;
    
    const druhObj = druhyObjednavkyOptions.find(opt =>
      (opt.kod_stavu && opt.kod_stavu === formData.druh_objednavky_kod) ||
      (opt.kod && opt.kod === formData.druh_objednavky_kod) ||
      (opt.value && opt.value === formData.druh_objednavky_kod)
    );
    
    // Kontrola atribut_objektu = 1 (majetek)
    return druhObj?.atribut_objektu === 1;
  }, [formData.druh_objednavky_kod, druhyObjednavkyOptions]);

  // 🆕 Helper: Formátování chybových hlášek do strukturované podoby
  const formatValidationErrors = React.useCallback((errors) => {
    if (!errors || Object.keys(errors).length === 0) return null;

    // ✅ SJEDNOCENO S FloatingNavigator.categorizeErrorKey() - MUSÍ BÝT 100% STEJNÉ!
    // Kategorizace chyb podle sekcí NAVIGÁTORU (odpovídá FloatingNavigator.js sekce IDs)
    const categories = {
      objednatel: { label: 'Informace o objednateli', errors: [] },
      schvaleni: { label: 'Schválení nákupu PO', errors: [] },
      dodavatel: { label: 'Dodavatel', errors: [] },
      detaily: { label: 'Detaily objednávky', errors: [] },
      stav_odeslani: { label: 'Odeslání objednávky', errors: [] },
      potvrzeni_objednavky: { label: 'Potvrzení objednávky dodavatelem', errors: [] },
      fakturace: { label: 'Fakturace', errors: [] },
      vecna_spravnost: { label: 'Věcná správnost', errors: [] },
      registr_smluv_vyplneni: { label: 'Registr smluv', errors: [] },
      ostatni: { label: 'Ostatní', errors: [] }
    };

    Object.entries(errors).forEach(([key, message]) => {
      // Vytvoř lidsky čitelnou zprávu (odstraň technické prefixy)
      let cleanMessage = message;
      
      // ✅ KRITICKÉ: Detekce kategorie MUSÍ být IDENTICKÁ s FloatingNavigator.categorizeErrorKey()
      // POŘADÍ JE DŮLEŽITÉ - specifičtější podmínky musí být PŘED obecnějšími!
      
      // 1. Informace o objednateli (včetně garanta!)
      if (key.includes('jmeno') || key.includes('email') || key.includes('ev_cislo') || key.includes('garant')) {
        categories.objednatel.errors.push(cleanMessage);
      }
      // 2. Schválení nákupu PO (FÁZE 1-2) - včetně FINANCOVÁNÍ!
      else if (key.includes('prikazce') || key.includes('max_cena') || 
               key.includes('strediska') || key.includes('predmet') ||
               key.includes('financovani') || key.includes('lp_kod') || key.includes('cislo_smlouvy') ||
               key.includes('individualni_schvaleni') || key.includes('pojistna_udalost')) {
        categories.schvaleni.errors.push(cleanMessage);
      }
      // 3. Detaily objednávky (FÁZE 3+: položky + druh + lokalizace) - MUSÍ BÝT PŘED dodavatelem!
      else if (key.startsWith('polozka_') || key.includes('druh_objednavky') || message.includes('Položka')) {
        categories.detaily.errors.push(cleanMessage);
      }
      // 4. Potvrzení objednávky dodavatelem - MUSÍ BÝT PŘED "dodavatel" (kvůli dodavatel_zpusob_potvrzeni)
      else if (key.includes('zpusob_potvrzeni') || key.includes('dt_akceptace') || key.includes('zpusob_platby')) {
        categories.potvrzeni_objednavky.errors.push(cleanMessage);
      }
      // 5. Dodavatel - MUSÍ BÝT PO potvrzení (kvůli dodavatel_zpusob_potvrzeni)
      else if (key.includes('dodavatel') || key.includes('ico') || key.includes('adresa') || key.includes('kontakt')) {
        categories.dodavatel.errors.push(cleanMessage);
      }
      // 6. Odeslání objednávky
      else if (key.includes('datum_odeslani') || key.includes('stav_odeslani')) {
        categories.stav_odeslani.errors.push(cleanMessage);
      }
      // 7. Věcná správnost - MUSÍ BÝT PŘED obecným "faktura_" - včetně LP čerpání
      else if ((key.startsWith('faktura_') && key.includes('vecna_spravnost')) || 
               key.startsWith('vecna_lp_') || 
               key.includes('vecna_poznamka')) {
        categories.vecna_spravnost.errors.push(cleanMessage);
      }
      // 8. Fakturace
      else if (key.startsWith('faktura_')) {
        categories.fakturace.errors.push(cleanMessage);
      }
      // 9. Registr smluv
      else if (key.includes('dt_zverejneni') || key.includes('registr') || key.includes('ma_byt_zverejnena')) {
        categories.registr_smluv_vyplneni.errors.push(cleanMessage);
      }
      // 10. Ostatní (fallback)
      else {
        categories.ostatni.errors.push(cleanMessage);
      }
    });

    // Sestavení strukturované zprávy - pouze neprázdné kategorie
    return (
      <div style={{ fontFamily: 'system-ui, -apple-system, sans-serif', lineHeight: '1.5' }}>
        <div style={{ 
          fontSize: '15px', 
          fontWeight: '600', 
          marginBottom: '12px', 
          color: '#1a1a1a',
          display: 'flex',
          alignItems: 'center',
          gap: '8px'
        }}>
          <AlertCircle size={20} color="#ff4d4f" style={{ flexShrink: 0 }} />
          <span>Pro uložení je nutné vyplnit následující položky:</span>
        </div>
        {Object.values(categories).map((cat, idx) => 
          cat.errors.length > 0 && (
            <div key={idx} style={{ 
              marginBottom: '10px',
              padding: '10px',
              backgroundColor: '#fff1f0',
              borderRadius: '4px'
            }}>
              <div style={{ 
                fontWeight: '600', 
                fontSize: '13px',
                color: '#d32f2f',
                marginBottom: '6px'
              }}>
                {cat.label}
              </div>
              {cat.errors.map((err, errIdx) => (
                <div key={errIdx} style={{ 
                  fontSize: '12px',
                  color: '#666',
                  marginLeft: '8px',
                  marginTop: '4px',
                  display: 'flex',
                  alignItems: 'flex-start'
                }}>
                  <span style={{ marginRight: '6px', color: '#ff4d4f', fontWeight: 'bold' }}>•</span>
                  <span>{err}</span>
                </div>
              ))}
            </div>
          )
        )}
      </div>
    );
  }, []);

  // 🆕 Kombinované options pro dodatečné dokumenty (PRILOHA_TYP + FAKTURA_TYP)
  // ✅ OPRAVA: Deduplikace podle value, aby nedošlo k duplicitním klíčům v React
  const dodatecneDokladyOptions = React.useMemo(() => {
    const combined = [...prilohyTypyOptions, ...typyFakturOptions];
    const uniqueMap = new Map();

    // Deduplikace - pokud je duplicitní value, ponecháme první výskyt
    combined.forEach(opt => {
      if (!uniqueMap.has(opt.value)) {
        uniqueMap.set(opt.value, opt);
      }
    });

    return Array.from(uniqueMap.values());
  }, [prilohyTypyOptions, typyFakturOptions]);

  // ✅ REFACTORED: areDictionariesReady nyní z formController.dictionaries.isReady
  const areDictionariesReady = dictionaries.isReady;

  // 🆕 State pro garant dropdown options (active users + inactive garant if editing)
  // Inicializuj HNED s aktivními uživateli pokud jsou k dispozici
  const [garantOptions, setGarantOptions] = useState(() => {
    const activeUsers = allUsers.filter(u => u.aktivni === 1 || u.aktivni === '1' || u.active === 1 || u.active === '1');
    return activeUsers;
  });

  // 🏛️ SYSTEM uživatel - přidá se JEN když má objednávka prikazce_id nebo schvalovatel_id = '0'
  // Používá se POUZE u archivovaných objednávek
  const approvers = useMemo(() => {
    const needsSystemUser = formData.prikazce_id === '0' || formData.schvalovatel_id === '0';

    // ✅ Rozšíření: Zahrnout i uživatele s rolí PRIKAZCE (i když nejsou v approversBase)
    // a zároveň vždy doplnit aktuálně vybraného příkazce/schvalovatele z allUsers,
    // aby filtrace LP měla k dispozici usek_id a nezobrazoval se fallback log.
    const getUserId = (u) => {
      const id = u?.id ?? u?.user_id;
      const n = typeof id === 'string' ? parseInt(id, 10) : id;
      return Number.isFinite(n) ? n : null;
    };

    const normalizeUser = (u) => {
      if (!u) return null;
      const id = getUserId(u);
      if (id === null || id === undefined) return null;
      return {
        ...u,
        // ⚠️ DŮLEŽITÉ: `id` musí být number (ne string).
        // filteredLpKodyOptions hledá: (user.id || user.user_id) === parseInt(formData.prikazce_id)
        // a používá strict ===, takže string by nikdy neshodoval.
        id,
        user_id: id
      };
    };

    const prikazciByRole = (allUsers || [])
      .filter(u => {
        const roles = u?.roles;
        return Array.isArray(roles) && roles.some(r => r?.kod_role === 'PRIKAZCE');
      })
      // preferujeme aktivní, ale necháme je projít – starší objednávky mohou mít neaktivního příkazce
      .map(normalizeUser)
      .filter(Boolean);

    const selectedIds = [formData.prikazce_id, formData.schvalovatel_id]
      .map(v => (v === null || v === undefined) ? null : parseInt(String(v), 10))
      .filter(v => Number.isFinite(v) && v > 0);

    const selectedUsers = selectedIds
      .map(id => normalizeUser((allUsers || []).find(u => getUserId(u) === id)))
      .filter(Boolean);

    // Merge: zachovat pořadí approversBase jako primární (má často displayName/usek_id z API)
    // + doplnit PRIKAZCE role a vybrané uživatele
    const merged = [
      ...(approversBase || []).map(normalizeUser).filter(Boolean),
      ...prikazciByRole,
      ...selectedUsers
    ];

    // Deduplikace dle user_id
    const unique = [];
    const seen = new Set();
    for (const u of merged) {
      const uid = getUserId(u);
      if (!uid || uid === 0) continue;
      if (seen.has(uid)) continue;
      seen.add(uid);
      unique.push(u);
    }

    if (!needsSystemUser) {
      return unique; // Běžné objednávky - bez SYSTEM
    }

    // Archivovaná objednávka s SYSTEM uživatelem
    return [
      {
        id: '0',
        jmeno: 'SYSTEM',
        prijmeni: '',
        displayName: 'SYSTEM',
        aktivni: 1,
        deaktivovan: 0
      },
      ...unique
    ];
  }, [approversBase, allUsers, formData.prikazce_id, formData.schvalovatel_id]);

  // Přejmenování pro zpětnou kompatibilitu (různé části kódu používají různé názvy)
  const fakturaTypyPrilohOptions = typyFakturOptions; // Alias
  const loadingFakturaTypyPriloh = false; // Číselníky už jsou načtené když se formulář zobrazuje

  // 🚀 CRITICAL FIX: Reset a povolit autosave při změně editOrderId
  useEffect(() => {
    const isNewOrder = !editOrderId;
    
    // ✅ FIX: RESET isDraftLoaded při změně editOrderId (přepnutí mezi objednávkami)
    setIsDraftLoaded(false);
    
    if (isNewOrder && user_id) {
      // 🔍 KRITICKÉ: Pro novou objednávku zkontrolovat zda existuje draft
      // Pokud ano, nechat useEffect níže ho načíst
      // Pokud ne, okamžitě nastavit isDraftLoaded=true
      const checkDraftAndInit = async () => {
        try {
          draftManager.setCurrentUser(user_id);
          const hasDraft = await draftManager.hasDraft();
          
          if (hasDraft) {
            // ✅ Existuje draft - načte se v useEffect níže
            setIsDraftLoaded(true); // Povolit načtení
          } else {
            // ✅ Neexistuje draft - nová čistá objednávka
            setIsDraftLoaded(true);
            // ✅ KRITICKÉ: Povolit autosave v DraftManageru!
            draftManager.setAutosaveEnabled(true, 'NEW order initialization');
          }
        } catch (error) {
          console.error('Chyba při kontrole draftu:', error);
          // Fallback - nastavit jako novou objednávku
          setIsDraftLoaded(true);
          draftManager.setAutosaveEnabled(true, 'NEW order initialization (fallback)');
        }
      };
      
      checkDraftAndInit();
    } else {
    }
  }, [editOrderId, user_id]); // Spustí se při změně editOrderId

  // Automatické rozbalení lokalizačních panelů s vyplněnými hodnotami
  // VŽDY rozbalit pokud:
  // 1. Je to majetková položka (atribut_objektu = 1) → POVINNÁ lokalizace
  // 2. Má vyplněná lokalizační data (úsek, budova, místnost, poznámka)
  useEffect(() => {
    if (formData.polozky_objednavky && Array.isArray(formData.polozky_objednavky)) {
      const newPanelStates = {};
      
      // Zkontroluj, jestli druh objednávky má atribut_objektu = 1 (majetek)
      const isMaterialOrderValue = isMaterialOrder;
      
      formData.polozky_objednavky.forEach(polozka => {
        // Zkontroluj, zda má položka vyplněná lokalizační data
        const hasLocationData =
          (polozka.usek_kod && polozka.usek_kod.trim() !== '') ||
          (polozka.budova_kod && polozka.budova_kod.trim() !== '') ||
          (polozka.mistnost_kod && polozka.mistnost_kod.trim() !== '') ||
          (polozka.poznamka && polozka.poznamka.trim() !== '');

        // ✅ ROZBALIT pokud:
        // - Je to majetek (lokalizace je POVINNÁ) → musí být vidět červené rámečky při validaci
        // - Má vyplněná data (aby uživatel viděl co už vyplnil)
        // 
        // DŮLEŽITÉ: Panel se rozbalí při:
        // - Načtení objednávky s majetkovými položkami (i když lokalizace není vyplněná)
        // - Načtení objednávky s vyplněnými lokalizačními daty
        // - Změně druhu objednávky na majetek
        if (isMaterialOrderValue || hasLocationData) {
          newPanelStates[polozka.id] = true;
        } else {
          // Zavřít pouze pokud NENÍ majetek A NEMÁ data
          newPanelStates[polozka.id] = false;
        }
      });

      // Nastav VŽDY - aby se panely mohly otevřít i zavřít při změně stavu
      setLokalizacePanelStates(newPanelStates);
    }
  }, [
    formData.polozky_objednavky?.length, 
    formData.druh_objednavky_kod, 
    isMaterialOrder,
    // ✅ KRITICKÉ: Sledovat i změny v lokalizačních datech položek
    // Když se načte objednávka z DB, musí se panely rozbalit
    JSON.stringify(formData.polozky_objednavky?.map(p => ({
      id: p.id,
      usek: p.usek_kod,
      budova: p.budova_kod,
      mistnost: p.mistnost_kod,
      poznamka: p.poznamka
    })))
  ])

  // Synchronizace smlouvaSearchTerm s formData.cislo_smlouvy při načtení dat
  useEffect(() => {
    if (formData.cislo_smlouvy && formData.cislo_smlouvy !== smlouvaSearchTerm) {
      setSmlouvaSearchTerm(formData.cislo_smlouvy);
    }
  }, [formData.cislo_smlouvy, smlouvaSearchTerm]);

  // JEDNODUCHÉ WORKFLOW - přímo z DB stavu bez mapování
  const [isConceptSaved, setIsConceptSaved] = useState(false); // Pouze localStorage koncept
  const [isPhase1Unlocked, setIsPhase1Unlocked] = useState(false); // Stav pro odemknutí FÁZE 1

  // 🎯 CENTRÁLNÍ NAČÍTÁNÍ DRAFTU při obnovení stránky (F5)
  // Tento useEffect se spustí když isDraftLoaded=true a není editOrderId v URL
  useEffect(() => {
    // Ochrana: Načíst draft pouze pokud:
    // 1. user_id existuje
    // 2. isDraftLoaded=true (inicializace dokončena)
    // 3. NENÍ editOrderId (editace se řeší v handleDataLoaded)
    if (!user_id || !isDraftLoaded || editOrderId) {
      return;
    }

    let isActive = true;

    const loadDraftData = async () => {
      try {
        draftManager.setCurrentUser(user_id);

        // Kontrola existence draftu
        const hasDraft = await draftManager.hasDraft();

        if (!hasDraft) {
          return;
        }

        // Načti draft
        const draftData = await draftManager.loadDraft();

        if (!draftData?.formData || !isActive) {
          return;
        }

        // 🔄 DB SYNC CHECK - pouze pro EDIT mode
        if (draftData.formData.id) {

          const syncCheck = await draftManager.checkDBSync(
            async (orderId) => {
              try {
                return await getOrderTimestampV2(orderId, token, username);
              } catch (error) {
                return null;
              }
            },
            async (orderId) => {
              try {
                const response = await getOrderV2(orderId, token, username);
                // ✅ KRITICKÉ: Transformovat data z backendu (parsovat JSON poznámky)
                const rawData = response?.data || null;
                return rawData ? transformBackendDataToFrontend(rawData) : null;
              } catch (error) {
                // 🌲 HIERARCHIE: Pokud backend vrátil 403, nemáme právo
                if (error?.status === 403 || error?.response?.status === 403) {
                  console.warn('⛔ HIERARCHY: Přístup k objednávce zamítnut hierarchií');
                }
                return null;
              }
            }
          );

          if (!isActive) return;

          if (syncCheck.needsSync && syncCheck.dbData) {
            // 🛡️ OCHRANA: Zachovat existující položky pokud DB data je nemá
            const mergedData = { ...syncCheck.dbData };
            if (!mergedData.polozky_objednavky || mergedData.polozky_objednavky.length === 0) {
              if (formData.polozky_objednavky && formData.polozky_objednavky.length > 0) {
                mergedData.polozky_objednavky = formData.polozky_objednavky;
                // DEBUG: Local items protection - logging removed
              }
            }

            setFormData(mergedData);
            setIsChanged(false);
            setIsEditMode(true);
            // 🔥 KRITICKÉ: Poslat broadcast po DB sync
            broadcastOrderState({
              isEditMode: true,
              isNewOrder: false,
              orderId: syncCheck.dbData.id,
              orderNumber: syncCheck.dbData.cislo_objednavky || syncCheck.dbData.ev_cislo
            });
            await draftManager.syncWithDatabase(syncCheck.dbData, syncCheck.dbData.id);
            return;
          }
        }

        // ✅ Aplikuj draft data

        // 🧹 VYČISTIT objekty ve fa_strediska_kod (pokud tam jsou)
        const cleanedDraftData = { ...draftData.formData };
        
        // ✅ TRANSFORMOVAT POLOŽKY Z DRAFTU - parsovat poznámky z JSON
        if (cleanedDraftData.polozky_objednavky && Array.isArray(cleanedDraftData.polozky_objednavky)) {
          cleanedDraftData.polozky_objednavky = cleanedDraftData.polozky_objednavky.map((item, idx) => {
            // ✅ JEDNODUŠE: Pokud je poznámka JSON string, parsuj a extrahuj poznamka_lokalizace
            let poznamkaText = '';
            
            if (item.poznamka) {
              if (typeof item.poznamka === 'string' && item.poznamka.trim().startsWith('{')) {
                try {
                  const parsed = JSON.parse(item.poznamka);
                  poznamkaText = parsed.poznamka_lokalizace || '';
                } catch {
                  // Není JSON → použij jak je
                  poznamkaText = item.poznamka;
                }
              } else {
                // Už je plain text
                poznamkaText = item.poznamka;
              }
            }
            
            const result = {
              ...item,
              poznamka: poznamkaText  // ✅ Vždy plain text
            };
            
            return result;
          });
        }

        // 🛡️ CRITICAL: Pokud je to NOVÁ objednávka (bez ID), vyčisti faktury!
        // Faktury z předchozí objednávky by se NIKDY neměly dostat do nové objednávky
        if (!cleanedDraftData.id) {
          // DRAFT CLEANUP: Odstraňuji faktury z draftu pro NOVOU objednávku
          cleanedDraftData.faktury = [];
        } else if (cleanedDraftData.faktury && Array.isArray(cleanedDraftData.faktury)) {
          // Pro existující objednávku pouze vyčisti fa_strediska_kod
          cleanedDraftData.faktury = cleanedDraftData.faktury.map(faktura => {
            if (faktura.fa_strediska_kod && Array.isArray(faktura.fa_strediska_kod)) {
              // Extrahovat jen stringy z objektů
              faktura.fa_strediska_kod = faktura.fa_strediska_kod.map(item => {
                if (typeof item === 'string') return item;
                return item.value || item.kod_stavu || item.id || item;
              });
            }
            return faktura;
          });
        }

        setFormData(prev => ({
          ...prev,  // ✅ KRITICKÉ: Zachovat všechny výchozí hodnoty (78 klíčů)
          ...cleanedDraftData,  // ✅ Přepsat jen změněné hodnoty z draftu (VYČIŠTĚNÉ!)
          id: prev?.id || draftData.formData.id,
          datum_posledni_zmeny: prev?.datum_posledni_zmeny || draftData.formData.datum_posledni_zmeny,
          // 🔧 FIX: Zachovat stav_schvaleni a strediska_kod z prev pokud draft neobsahuje validní hodnoty
          // prev obsahuje už SPRÁVNĚ TRANSFORMOVANÁ data z useOrderDataLoader
          stav_schvaleni: cleanedDraftData.stav_schvaleni || prev?.stav_schvaleni || '',
          strediska_kod: (cleanedDraftData.strediska_kod && Array.isArray(cleanedDraftData.strediska_kod) && cleanedDraftData.strediska_kod.length > 0)
            ? cleanedDraftData.strediska_kod
            : (prev?.strediska_kod || []),
          // 🔧 FIX: dodavatel_zpusob_potvrzeni - použít draft JEN pokud má NEPRÁZDNÉ zpusoby
          // Pokud je pole prázdné, zachovat hodnotu z DB (prev)
          dodavatel_zpusob_potvrzeni: (cleanedDraftData.dodavatel_zpusob_potvrzeni?.zpusoby?.length > 0)
            ? cleanedDraftData.dodavatel_zpusob_potvrzeni
            : (prev?.dodavatel_zpusob_potvrzeni || cleanedDraftData.dodavatel_zpusob_potvrzeni)
        }));

        setIsChanged(draftData.isChanged === true);

        if (draftData.formData.id || draftData.formData?.id) {
          setIsEditMode(true);
          // 🔥 KRITICKÉ: Poslat broadcast po načtení draftu s editId
          broadcastOrderState({
            isEditMode: true,
            isNewOrder: false,
            orderId: draftData.formData.id,
            orderNumber: draftData.formData.cislo_objednavky || draftData.formData.ev_cislo
          });
        }

      } catch (error) {
      }
    };

    loadDraftData();

    return () => {
      isActive = false;
    };
  }, [user_id, isDraftLoaded, editOrderId]); // ✅ Spustí se když isDraftLoaded=true a není editOrderId

  // Flag pro kontrolu odeslání už není potřeba - odvozuje se přímo z DB stavu

  // Všechno odvozené přímo z formData.stav_workflow_kod (DB stav) - useMemo optimalizace
  const isOrderSavedToDB = useMemo(() => !!formData.id, [formData.id]);
  const isApprovedOrder = useMemo(() => {
    const states = Array.isArray(formData.stav_workflow_kod) ? formData.stav_workflow_kod : parseWorkflowStates(formData.stav_workflow_kod);
    return states.includes('SCHVALENA');
  }, [formData.stav_workflow_kod]);

  const sectionVisibility = getSectionVisibility(mainWorkflowState, currentPhase, isArchived);

  // Mapování sekcí na jejich pevné barvy podle typu
  const getSectionTheme = (sectionName) => {
    const sectionColorMap = {
      // ŠEDÉ sekce (základní info)
      'objednatel': 'section-grey',
      'schvaleni': 'section-grey',

      // ORANŽOVÉ sekce (příprava objednávky)
      'financovani': 'section-orange',
      'dodavatel': 'section-orange',
      'detaily': 'section-orange',
      'dodaci_podminky': 'section-orange',
      'stav_odeslani': 'section-orange',

      // ČERVENÁ sekce (přílohy - mimo workflow)
      'prilohy': 'section-red',

      // MODRÉ sekce (potvrzení a realizace)
      'potvrzeni_objednavky': 'section-blue',
      'registr_smluv': 'section-blue',
      'prubeh_objednavky': 'section-blue',
      'dodaci_informace': 'section-blue',
      'fakturace': 'section-blue',
      'storno_detail': 'section-blue',

      // FIALOVÉ sekce (registr - potvrzení zveřejnění)
      'registr_smluv_vyplneni': 'section-purple'
    };

    return sectionColorMap[sectionName] || 'section-orange'; // default oranžová
  };

  // 🔧 FIX: Define canEditPhase2 before isSectionActive uses it
  const canEditPhase2 = hasPermission && (hasPermission('ORDER_MANAGE') || hasPermission('ORDER_APPROVE') || hasPermission('ORDER_EDIT_OWN') || hasPermission('ORDER_EDIT_ALL')); // Pro odemykání FÁZE 2

  // Určení, zda je sekce aktivní podle aktuální fáze
  const isSectionActive = useCallback((sectionName) => {
    const phase = currentPhase; // 🔧 Use pre-calculated currentPhase instead of getCurrentPhase()

    // FÁZE 1: Základní info sekce jsou vždy aktivní + financování a detaily pro uživatele s oprávněním
    if (phase === 1) {
      const basicSections = ['objednatel', 'schvaleni'];
      const phase2SectionsForAuthorizedUsers = ['financovani', 'detaily'];

      // Základní sekce jsou vždy aktivní ve FÁZI 1
      if (basicSections.includes(sectionName)) {
        return true;
      }

      // Pokud má uživatel oprávnění k editaci objednávek, povolí také klíčové sekce FÁZE 2
      if (canEditPhase2 && phase2SectionsForAuthorizedUsers.includes(sectionName)) {
        return true;
      }

      return false;
    }

    // FÁZE 2: Příprava objednávky - oranžové sekce aktivní
    if (phase === 2) {
      return ['financovani', 'dodavatel', 'detaily', 'dodaci_podminky', 'prilohy', 'stav_odeslani'].includes(sectionName);
    }

    // FÁZE 3+: Potvrzení a realizace - modré sekce aktivní
    if (phase >= 3) {
      return ['potvrzeni_objednavky', 'registr_smluv', 'prubeh_objednavky', 'dodaci_informace', 'fakturace', 'storno_detail'].includes(sectionName);
    }

    return false; // Default neaktivní
  }, [currentPhase, canEditPhase2]); // 🔧 Add dependencies for useCallback

  // Kontrola oprávnění pro schvalování objednávek
  const canApproveOrders = hasPermission && hasPermission('ORDER_APPROVE');
  const canManageOrders = hasPermission && hasPermission('ORDER_MANAGE');
  const canManageUsers = hasPermission && hasPermission('USER_MANAGE'); // Pro práci s kontakty
  const canEditPhase3 = hasPermission && (hasPermission('ORDER_MANAGE') || hasPermission('ORDER_EDIT_OWN') || hasPermission('ORDER_EDIT_ALL')); // Pro odemykání FÁZE 3
  const canEditApprovedSections = canApproveOrders || canManageOrders;
  const canPublishRegistry = hasPermission && hasPermission('ORDER_PUBLISH_REGISTRY'); // 🆕 Pro editaci polí registru smluv
  const canManageInvoices = hasPermission && hasPermission('INVOICE_MANAGE'); // 🆕 Pro editaci faktur ve Fázi 7
  const canSaveOrder = hasPermission && (hasPermission('ORDER_MANAGE') || hasPermission('ORDER_APPROVE') || hasPermission('ORDER_EDIT_OWN') || hasPermission('ORDER_EDIT_ALL')); // Pro ukládání objednávek (včetně schválení)

  // Kontrola rolí pro speciální oprávnění - MUSÍ BÝT PŘED použitím!
  const isSuperAdmin = userDetail?.roles?.some(role => role.kod_role === 'SUPERADMIN');
  const isAdmin = userDetail?.roles?.some(role => role.kod_role === 'ADMINISTRATOR');
  const isPrikazce = userDetail?.roles?.some(role => role.kod_role === 'PRIKAZCE');
  const hasOrderManagePermission = hasPermission && hasPermission('ORDER_MANAGE');
  const canUnlockAnything = isSuperAdmin || isAdmin || hasOrderManagePermission; // SUPER, ADMIN a ORDER_MANAGE mohou odemknout cokoliv

  const isPrikazceOfOrder = formData.prikazce_id && parseInt(formData.prikazce_id, 10) === user_id;

  // 🆕 Schválení kolegou: jiný příkazce ze STEJNÉHO úseku může schválit objednávku
  // (příklad: úsek PTU – objednávku s příkazcem Fajka může schválit i Sulgan)
  const canApproveAsSameUsekPrikazce = useMemo(() => {
    try {
      if (!isPrikazce) return false;
      const prikazceIdRaw = formData.prikazce_id;
      const prikazceId = prikazceIdRaw ? parseInt(String(prikazceIdRaw), 10) : null;
      if (!prikazceId || !Number.isFinite(prikazceId)) return false;
      if (!user_id || !Number.isFinite(user_id)) return false;
      if (prikazceId === user_id) return true; // je to přímo příkazce objednávky

      const getUid = (u) => {
        const id = u?.id ?? u?.user_id;
        const n = typeof id === 'string' ? parseInt(id, 10) : id;
        return Number.isFinite(n) ? n : null;
      };

      const normalizeUsekZkr = (val) => {
        if (!val) return [];
        if (Array.isArray(val)) return val.filter(Boolean).map(v => String(v).trim()).filter(Boolean);
        if (typeof val === 'string') {
          const t = val.trim();
          if (!t || t === 'null' || t === '[]') return [];
          if (t.startsWith('[')) {
            try {
              const parsed = JSON.parse(t);
              if (Array.isArray(parsed)) return parsed.filter(Boolean).map(v => String(v).trim()).filter(Boolean);
            } catch {
              // ignore
            }
          }
          return [t];
        }
        return [String(val).trim()].filter(Boolean);
      };

      const me = (allUsers || []).find(u => getUid(u) === user_id);
      const prikazce = (approvers || []).find(u => getUid(u) === prikazceId)
        || (allUsers || []).find(u => getUid(u) === prikazceId);

      const myUsekId = me?.usek_id ?? me?.usek;
      const prikazceUsekId = prikazce?.usek_id ?? prikazce?.usek;

      // Primárně dle usek_id (spolehlivější)
      if (myUsekId && prikazceUsekId) {
        return String(myUsekId) === String(prikazceUsekId);
      }

      // Fallback dle usek_zkr (může být string / JSON string / array)
      const myUsekyZkr = normalizeUsekZkr(me?.usek_zkr);
      const prikazceUsekyZkr = normalizeUsekZkr(prikazce?.usek_zkr);
      if (myUsekyZkr.length === 0 || prikazceUsekyZkr.length === 0) return false;
      return myUsekyZkr.some(zkr => prikazceUsekyZkr.includes(zkr));
    } catch {
      return false;
    }
  }, [allUsers, approvers, formData.prikazce_id, isPrikazce, user_id]);

  // 🆕 Rozšířená logika schvalování podle zadání:
  // - příkazce objednávky
  // - jiný příkazce ze stejného úseku
  // - SUPERADMIN / ADMINISTRATOR
  // - uživatel s právy ORDER_APPROVE / ORDER_MANAGE
  const canViewApprovalSection = isPrikazceOfOrder || canApproveAsSameUsekPrikazce || isSuperAdmin || isAdmin || canApproveOrders || canManageOrders;

  // 🔒 EDITACE VE FÁZI 2 (KE SCHVÁLENÍ)
  // Běžný uživatel po znovu-otevření nesmí upravovat sekce Objednatel/Schválení/Financování.
  // Výjimka: role/permission pro schvalování nebo správu (ORDER_APPROVE/ORDER_MANAGE), příkazce objednávky, admin.
  const canEditDuringApprovalPhase = canManageOrders || canApproveOrders || isPrikazceOfOrder || isSuperAdmin || isAdmin;

  // 💰 Helper: Jednotná detekce LP financování (primárně dle KÓDU, fallback dle názvu v číselníku)
  // DŮVOD: detekce dle názvu je citlivá na timing (financovaniOptions nemusí být ready) a na změny textů.
  // Tento helper se používá pro:
  // - zobrazení LP sekcí
  // - validace (Save i silent)
  // - LP logiku u položek
  const isLPFinancing = useCallback(() => {
    try {
      const raw = formData.zpusob_financovani;
      const code = (raw === null || raw === undefined) ? '' : String(raw).trim().toUpperCase();
      if (code === 'LP' || code === 'LIMITOVANY_PRISLIB' || code === 'LIMITOVANÝ_PŘÍSLIB') {
        return true;
      }

      // Fallback: dohledat option a zkontrolovat název (kvůli historickým/nekonzistentním hodnotám)
      const selected = financovaniOptions.find(opt =>
        opt.kod === raw ||
        opt.kod_stavu === raw ||
        opt.value === raw
      );
      const nazev = (selected?.nazev_stavu || selected?.nazev || '').toLowerCase();
      return nazev.includes('limitovan') && (nazev.includes('prislib') || nazev.includes('příslib'));
    } catch {
      return false;
    }
  }, [formData.zpusob_financovani, financovaniOptions]);

  // 🎯 Filtrované LP kódy podle úseku vybraného příkazce a platnosti
  // MUSÍ být AŽ PO definici isSuperAdmin a approvers!
  const filteredLpKodyOptions = React.useMemo(() => {
    // Pokud není vybraný příkazce, vrátit všechny LP kódy
    if (!formData.prikazce_id) {
      return lpKodyOptions;
    }

    // Najít vybraného příkazce v seznamu approvers
    const selectedPrikazce = approvers.find(user => 
      (user.id || user.user_id) === parseInt(formData.prikazce_id)
    );

    // Pokud příkazce nenalezen, vrátit všechny LP kódy
    if (!selectedPrikazce) {
      // 📝 NOTE: Toto je normální při editaci starých objednávek kde příkazce už nemá ORDER_APPROVE právo
      // nebo byl deaktivován. V tom případě zobrazíme všechny LP kódy bez filtrace.
      if (process.env.NODE_ENV === 'development') {
        console.info('ℹ️ Příkazce není v seznamu aktivních approvers (možná starší objednávka nebo změna role) - zobrazuji všechny LP kódy');
      }
      return lpKodyOptions;
    }

    // 🔓 VÝJIMKA: Pokud je VYBRANÝ PŘÍKAZCE SUPERADMIN → zobrazit VŠECHNY LP kódy
    // (kontrolujeme roli VYBRANÉHO příkazce, ne přihlášeného uživatele!)
    // Najít příkazce v allUsers (kde jsou role)
    const prikazceWithRoles = allUsers.find(u => 
      (u.id || u.user_id) === parseInt(formData.prikazce_id)
    );
    const prikazceIsSuperAdmin = prikazceWithRoles?.roles?.some(role => role.kod_role === 'SUPERADMIN');
    
    if (prikazceIsSuperAdmin) {
      // Stále aplikovat filtr platnosti
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      
      return lpKodyOptions.filter(lp => {
        const platneOd = lp.platne_od ? new Date(lp.platne_od) : null;
        const platneDo = lp.platne_do ? new Date(lp.platne_do) : null;
        if (platneOd) platneOd.setHours(0, 0, 0, 0);
        if (platneDo) platneDo.setHours(0, 0, 0, 0);
        return (!platneOd || platneOd <= today) && (!platneDo || platneDo >= today);
      });
    }

    // Získat usek_id příkazce (už by měl být v response z API)
    const prikazceUsekId = selectedPrikazce.usek_id;
    
    if (!prikazceUsekId) {
      console.warn('⚠️ Příkazce nemá usek_id:', selectedPrikazce);
      return lpKodyOptions;
    }

    // Aktuální datum pro kontrolu platnosti
    const today = new Date();
    today.setHours(0, 0, 0, 0); // Normalizovat na půlnoc

    // Filtrovat LP kódy podle usek_id a platnosti
    const filtered = lpKodyOptions.filter(lp => {
      // 1. Kontrola úseku
      const lpUsekId = lp.usek_id || lp.usek;
      if (!lpUsekId || String(lpUsekId) !== String(prikazceUsekId)) {
        return false;
      }

      // 2. Kontrola platnosti (platne_od / platne_do)
      const platneOd = lp.platne_od ? new Date(lp.platne_od) : null;
      const platneDo = lp.platne_do ? new Date(lp.platne_do) : null;

      // Normalizovat datumy na půlnoc
      if (platneOd) platneOd.setHours(0, 0, 0, 0);
      if (platneDo) platneDo.setHours(0, 0, 0, 0);

      // LP musí být platné DNES
      // - pokud má platne_od, musí být <= today
      // - pokud má platne_do, musí být >= today
      const jeAktivni = 
        (!platneOd || platneOd <= today) && 
        (!platneDo || platneDo >= today);

      return jeAktivni;
    });

    return filtered;
  }, [formData.prikazce_id, lpKodyOptions, approvers, allUsers]);

  // 🔒 WORKFLOW LOCKING - isWorkflowCompleted, isWorkflowRejected, isWorkflowCancelled
  // přicházejí z workflowManager. WorkflowManager řídí zamykání CENTRÁLNĚ přes isWorkflowCompleted.
  // isWorkflowCompleted = TRUE pro DOKONCENA, ZAMITNUTA, ZRUSENA (všechny konečné stavy workflow)
  // SUPER/ADMIN/ORDER_MANAGE mohou odemknout přes unlock dialogy.
  
  // 🔒 CENTRÁLNÍ ZAMYKÁNÍ PRO PŘÍLOHY: Použití workflowManager.getSectionState() pro správné zamykání
  // Sekce 'prilohy' NENÍ v SECTION_DEFINITIONS, takže použijeme fallback na isWorkflowCompleted
  const isPrilohyLocked = useMemo(() => {
    // ✅ SPRÁVNÁ LOGIKA: Přílohy jsou zamčené když je workflow dokončeno
    // ⚠️ DŮLEŽITÉ: Přílohy jsou zamčené PRO VŠECHNY včetně adminů (není možnost odemčení)
    // Důvod: Přílohy k dokončené/zamítnuté/stornované objednávce by neměly být měnitelné
    return isWorkflowCompleted;
  }, [isWorkflowCompleted]);

  // 🎯 NOVÉ: Použít centralizované section states z workflowManager
  // ✅ WorkflowManager vrací { visible, enabled } pro každou sekci (bez unlock states parametru)
  // � FIX: Stable section states - pouze závislost na klíčových hodnotách, ne na celém workflowManager
  const allSectionStates = useMemo(() => {
    return workflowManager.getAllSectionStates({
      canEditDuringApprovalPhase
    });
  }, [currentPhase, formData.id, isArchived, formData.stav_workflow_kod, formData.potvrzeni_dokonceni_objednavky, workflowManager, canEditDuringApprovalPhase]); // ✅ Kompletní dependencies pro refresh

  // 🐛 FIX: Memoize formData for FloatingNavigator to prevent re-renders
  // 🎯 Include faktury for věcná správnost validation badge
  const navigatorFormData = useMemo(() => ({ 
    id: formData.id,
    faktury: formData.faktury,
    max_cena_s_dph: formData.max_cena_s_dph
  }), [formData.id, formData.faktury, formData.max_cena_s_dph]);

  // 📎 Helper: Počítání příloh a jejich stavů
  const getAttachmentsInfo = useMemo(() => {
    if (!attachments || attachments.length === 0) {
      return { count: 0, hasErrors: false };
    }

    const count = attachments.length;
    // ✅ Chyba = soubor neexistuje (file_exists: false), status: 'error', nebo chybí klasifikace
    const hasErrors = attachments.some(att => 
      att.file_exists === false || 
      att.status === 'error' || 
      att.status === 'failed' ||
      !att.klasifikace || 
      att.klasifikace.trim() === ''
    );

    return { count, hasErrors };
  }, [attachments]);

  // 🎯 Rozšířené section states pro navigator - zahrnuje inline podmínky viditelnosti
  const extendedSectionStates = useMemo(() => {
    const states = { ...allSectionStates };
    
    // 🔒 PŘÍLOHY - manuální přidání stavu (není v SECTION_DEFINITIONS)
    // Viditelné pouze když má objednávka ID, zamčené když je workflow dokončeno
    if (formData.id) {
      states.prilohy = {
        visible: true,  // Vždy viditelné když má objednávka ID
        enabled: !isPrilohyLocked,  // Odemčené pouze když není workflow dokončeno
        attachmentsCount: getAttachmentsInfo.count,  // ✅ Počet příloh
        hasAttachmentErrors: getAttachmentsInfo.hasErrors  // ✅ Stav chyb
      };
    }
    
    // Fakturace - upravit viditelnost podle práv a vyplněných dat
    const isPlatbaPokladnaObj = formData.financovani?.platba === 'pokladna';
    const isPlatbaPokladnaDodavatel = formData.dodavatel_zpusob_potvrzeni?.platba === 'pokladna';
    const isPokladna = isPlatbaPokladnaObj || isPlatbaPokladnaDodavatel;
    const hasFaktury = !!(formData.faktury && formData.faktury.length > 0); // ✅ OPRAVA: Vždy boolean
    
    if (states.fakturace) {
      states.fakturace = {
        ...states.fakturace,
        visible: !isPokladna && (
          canManageInvoices 
            ? currentPhase >= 6 
            : (currentPhase >= 7 || hasFaktury)
        )
      };
    }
    
    // Registr smluv vyplnění - upravit viditelnost podle práv a vyplněných dat
    // 🔒 PRAVIDLA VIDITELNOSTI:
    // 1. Má uživatel právo ORDER_PUBLISH_REGISTRY → viditelná podle WorkflowManager
    // 2. Nemá právo, ale data jsou vyplněná A sekce je zamčená → viditelná jako readonly
    // 3. Nemá právo, data nejsou vyplněná NEBO sekce není zamčená → SKRYTÁ
    const isRegistrFilled = formData.dt_zverejneni && formData.registr_iddt;
    if (states.registr_smluv_vyplneni) {
      const workflowVisible = states.registr_smluv_vyplneni.visible;
      const isLocked = !states.registr_smluv_vyplneni.enabled;
      
      // Viditelná jen pokud:
      // - Má právo (bez ohledu na stav) NEBO
      // - Nemá právo, ale data jsou vyplněná A sekce je zamčená (readonly režim)
      const shouldBeVisible = workflowVisible && (
        canPublishRegistry || (isRegistrFilled && isLocked)
      );
      
      states.registr_smluv_vyplneni = {
        ...states.registr_smluv_vyplneni,
        visible: shouldBeVisible
      };
    }
    
    // 🔒 DOKONČENÍ - rozšířit viditelnost pro ADMIN + ORDER_MANAGE
    // WorkflowManager kontroluje stav DOKONCENA, my přidáme viditelnost pro adminy ve fázi 8+
    if (states.dokonceni && canUnlockAnything && currentPhase >= 8) {
      states.dokonceni = {
        ...states.dokonceni,
        visible: true  // Admin vidí sekci od fáze 8 (i když není dokončená)
      };
    }
    
    return states;
  }, [allSectionStates, currentPhase, canManageInvoices, canPublishRegistry, 
      formData.financovani?.platba, formData.dodavatel_zpusob_potvrzeni?.platba, 
      formData.faktury, formData.dt_zverejneni, formData.registr_iddt, 
      formData.id, isPrilohyLocked, canUnlockAnything, getAttachmentsInfo]);

  // 🔧 HELPER: Zjistí jestli je pole disabled (kombinace workflow lock + UI stav)
  const isFieldDisabled = useCallback((sectionState) => {
    return !sectionState.enabled || showSaveProgress || isSaving;
  }, [showSaveProgress, isSaving]);

  // ✅ NOVÉ: Použít workflowManager pro section states
  const registrState = allSectionStates.registr_smluv;
  const isRegistrLocked = !registrState.enabled; // Locked = !enabled

  const registrVyplneniState = allSectionStates.registr_smluv_vyplneni;
