                  objednatel_id: formData.objednatel_id || user_id,  // ✅ OPRAVA: Přidat fallback
                  uzivatel_id: formData.objednatel_id || user_id,  // ✅ OPRAVA: Pro hierarchii která používá uzivatel_id
