// Helper funkce pro normalizaci textu (odstranění diakritiky pro vyhledávání)
const normalizeSearchText = (text) => {
  if (!text) return '';
  return text
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
};

// Nový stabilní CustomSelect s jednoduchým state managementem
const StableCustomSelect = React.memo(({
  value,
  onChange,
  onBlur,
  options = [],
  placeholder = "Vyberte...",
  disabled = false,
  hasError = false,
  required = false,
  field,
  loading = false,
  loadingText = 'Načítání...',
  icon = null,
  multiple = false,
  isClearable = false,
  getOptionLabel,
  getOptionValue,
  hasTriedToSubmit = false
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [internalScroll, setInternalScroll] = useState(0);

  const wrapperRef = useRef(null);
  const buttonRef = useRef(null);
  const dropdownRef = useRef(null);
  const searchInputRef = useRef(null);
  const voiceInputFlagRef = useRef(false); // Flag pro hlasový vstup

  // Zpracování hodnot
  const normalizedValue = multiple ? (Array.isArray(value) ? value : []) : value;

  // Filtrované možnosti
  const filteredOptions = useMemo(() => {
    if (!searchTerm || loading) return options;

    // Normalizace hledaného textu (bez diakritiky)
    const normalizedSearch = normalizeSearchText(searchTerm);

    return options.filter(option => {
      let label;
      if (getOptionLabel) {
        label = getOptionLabel(option, field);
      } else {
        // Fallback pro různé typy objektů
        if (field === 'strediska' || field === 'strediska_kod') {
          label = option.label || option.name || option.nazev_stavu || String(option);
        } else if (field === 'lp_kod') {
          label = option.cislo_lp ? `${option.cislo_lp} - ${option.nazev_uctu || ''}` : option.label || String(option);
        } else {
          label = option.label || option.nazev || option.name || String(option);
        }
      }

      // Normalizace labelu (bez diakritiky) pro porovnání
      const normalizedLabel = normalizeSearchText(label);
      return normalizedLabel.includes(normalizedSearch);
    });
  }, [options, searchTerm, loading, getOptionLabel, field]);

  // Display hodnota
  const displayValue = useMemo(() => {
    if (multiple) {
      if (normalizedValue.length === 0) return placeholder;

      const result = normalizedValue.map(val => {
        const option = options.find(opt => {
          const optVal = getOptionValue ? getOptionValue(opt, field) : (opt.id || opt.value || opt.kod_stavu || opt.kod || opt);
          // OPRAVA: Porovnání i pro string vs number (např. '26' vs 26)
          return optVal == val;
        });

        if (option) {
          // Použij externí getOptionLabel funkci nebo fallback
          if (getOptionLabel) {
            return getOptionLabel(option, field);
          }
          // Fallback pro různé typy objektů
          if (field === 'strediska' || field === 'strediska_kod') {
            return option.label || option.name || option.nazev_stavu || String(option);
          }
          if (field === 'lp_kod') {
            // OPRAVA: Použij label, který už je správně naformátovaný při načítání LP kódů
            return option.label || (option.cislo_lp ? `${option.cislo_lp} - ${option.nazev_uctu || ''}` : String(option));
          }
          return option.label || option.nazev || option.name || String(option);
        }

        return String(val);
      }).join(', ');

      return result;
    } else {
      if (!normalizedValue) return placeholder;
      const option = options.find(opt => {
        const optVal = getOptionValue ? getOptionValue(opt, field) : (opt.id || opt.value || opt.kod_stavu || opt.kod || opt);
        // OPRAVA: Porovnání i pro string vs number (např. '26' vs 26)
        return optVal == normalizedValue; // Používáme == místo === pro type coercion
      });
      if (option) {
        if (getOptionLabel) {
          return getOptionLabel(option, field);
        }
        return option.label || option.nazev || option.name || String(option);
      }
      // Pokud není nalezen option a jde o prikazce nebo schvalovatel s hodnotou 0 nebo null, zobraz "Neznámý"
      if ((field === 'prikazce' || field === 'schvalovatel') && (normalizedValue === 0 || normalizedValue === null || normalizedValue === '0')) {
        return 'Neznámý';
      }
      return String(normalizedValue);
    }
  }, [normalizedValue, options, placeholder, multiple, getOptionLabel, getOptionValue, field]);

  // Zavření při kliknutí mimo
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target)) {
        setIsOpen(false);
        setSearchTerm('');
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [isOpen]);

  // Auto-focus search při otevření
  useEffect(() => {
    if (isOpen && searchInputRef.current && filteredOptions.length > 0) {
      setTimeout(() => searchInputRef.current?.focus(), 100);
    }
  }, [isOpen, filteredOptions.length]);

  // Detekce hlasového vstupu (nastaveno v useGlobalVoiceRecognition.js)
  useEffect(() => {
    if (!wrapperRef.current) return;

    const checkVoiceInputAttribute = () => {
      const hasVoiceInput = wrapperRef.current?.hasAttribute('data-voice-input');
      if (hasVoiceInput && !voiceInputFlagRef.current) {
        voiceInputFlagRef.current = true;
        // NEODSTRAŇUJ atribut hned - nech ho tam pro případ dalších kontrol
      }
    };

    // Kontroluj okamžitě
    checkVoiceInputAttribute();

    // A také při změně searchTerm (voice input mění hodnotu)
    if (searchTerm) {
      checkVoiceInputAttribute();
    }
  }, [searchTerm, field]);

  // Automatický výběr při 1 výsledku po filtrování (pouze pro hlasové ovládání)
  useEffect(() => {
    if (isOpen && searchTerm && filteredOptions.length === 1 && !multiple && voiceInputFlagRef.current) {
      // Pokud je jen 1 výsledek po filtrování A je to hlasový vstup → automaticky vyber po krátkém delay
      const timer = setTimeout(() => {
        const option = filteredOptions[0];
        const optionValue = getOptionValue ? getOptionValue(option, field) : (option.id || option.value || option);

        // Zkontroluj, jestli už není vybraná
        if (normalizedValue !== optionValue) {
          onChange(optionValue);
          if (onBlur) onBlur(field, optionValue);
          setIsOpen(false);
          setSearchTerm('');
          voiceInputFlagRef.current = false; // Reset flag
          // Odstraň atribut po auto-výběru
          if (wrapperRef.current) {
            wrapperRef.current.removeAttribute('data-voice-input');
          }
        }
      }, 500); // 500ms delay pro jistotu, že uživatel už nepíše

      return () => clearTimeout(timer);
    }
  }, [isOpen, searchTerm, filteredOptions, multiple, getOptionValue, field, normalizedValue, onChange, onBlur]);

  // Pozicování dropdown
  useEffect(() => {
    if (isOpen && buttonRef.current && dropdownRef.current) {
      const updatePosition = () => {
        if (!buttonRef.current || !dropdownRef.current) return;
        const buttonRect = buttonRef.current.getBoundingClientRect();
        const dropdown = dropdownRef.current;

        const dropdownMaxHeight = 300;
        const footerHeight = 54; // Výška fixní patičky
        const buffer = 20; // Extra buffer pro bezpečnost
        const spaceBelow = window.innerHeight - buttonRect.bottom - footerHeight - buffer;
        const spaceAbove = buttonRect.top - buffer;
        // Otevři nahoru pokud: není dost místa dole NEBO je nahoře výrazně více místa
        const shouldOpenUpward = spaceBelow < 200 || (spaceBelow < dropdownMaxHeight && spaceAbove > spaceBelow + 50);

        dropdown.style.left = buttonRect.left + 'px';
        dropdown.style.width = buttonRect.width + 'px';
        dropdown.style.maxHeight = dropdownMaxHeight + 'px';

        if (shouldOpenUpward) {
          // Otevřít nahoru
          dropdown.style.bottom = (window.innerHeight - buttonRect.top + 2) + 'px';
          dropdown.style.top = 'auto';
        } else {
          // Otevřít dolů (standardní chování)
          dropdown.style.top = (buttonRect.bottom + 2) + 'px';
          dropdown.style.bottom = 'auto';
        }
      };

      updatePosition();

      const handleScroll = (event) => {
        // Neaktualizovat při scrollu uvnitř dropdown
        if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
          updatePosition();
        }
      };

      // Používat capture: true pro zachycení všech scroll eventů
      window.addEventListener('scroll', handleScroll, { passive: true, capture: true });
      window.addEventListener('resize', updatePosition, { passive: true });

      return () => {
        window.removeEventListener('scroll', handleScroll, { capture: true });
        window.removeEventListener('resize', updatePosition);
      };
    }
  }, [isOpen]);

  // Zachování scroll pozice
  useEffect(() => {
    if (dropdownRef.current && internalScroll > 0) {
      dropdownRef.current.scrollTop = internalScroll;
    }
  }, [filteredOptions, internalScroll]);

  const handleToggle = () => {
    if (disabled) return;

    const newState = !isOpen;
    setIsOpen(newState);

    if (isOpen) {
      setSearchTerm('');
    }
  };

  const handleOptionClick = (option) => {
    // Zachovat scroll pozici
    if (dropdownRef.current) {
      setInternalScroll(dropdownRef.current.scrollTop);
    }

    const optionValue = getOptionValue ? getOptionValue(option, field) : (option.id || option.value || option);

    if (multiple) {
      const currentValues = Array.isArray(normalizedValue) ? normalizedValue : [];
      const newValues = currentValues.includes(optionValue)
        ? currentValues.filter(v => v !== optionValue)
        : [...currentValues, optionValue];

      // Pro multiselect pošli pole přímo
      onChange(newValues);
      if (onBlur) onBlur(field, newValues);
    } else {
      // Pro single select pošli hodnotu přímo
      onChange(optionValue);
      if (onBlur) onBlur(field, optionValue);
      setIsOpen(false);
      setSearchTerm('');
      // Reset voice input flag při ručním výběru
      voiceInputFlagRef.current = false;
      if (wrapperRef.current) {
        wrapperRef.current.removeAttribute('data-voice-input');
      }
    }
  };

  const isSelected = (option) => {
    const optionValue = getOptionValue ? getOptionValue(option, field) : (option.id || option.value || option);
    return multiple
      ? normalizedValue.includes(optionValue)
      : normalizedValue === optionValue;
  };

  // Automatická detekce chyby pro povinná pole (stejně jako v CustomSelect.js)
  const hasValue = multiple
    ? (Array.isArray(normalizedValue) && normalizedValue.length > 0)
    : !!normalizedValue;
  const shouldShowError = hasError || (required && !hasValue && !loading && !disabled && hasTriedToSubmit);

  return (
    <StableSelectWrapper ref={wrapperRef} data-stable-select data-field={field}>
      <StableSelectButton
        ref={buttonRef}
        type="button"
        onClick={handleToggle}
        disabled={disabled}
        hasError={shouldShowError}
        isOpen={isOpen}
        hasValue={hasValue}
        hasIcon={!!icon}
        data-field={field}
      >
        {icon && (
          <span style={{
            position: 'absolute',
            left: '12px',
            color: '#9ca3af',
            width: '16px',
            height: '16px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}>
            {React.cloneElement(icon, { size: 16 })}
          </span>
        )}
        <StableSelectValue title={displayValue} $hasValue={hasValue} $disabled={disabled}>
          {(() => {
            // 🏷️ Check if selected option is majetek for druh_objednavky_kod
            if (field === 'druh_objednavky_kod' && normalizedValue) {
              const selectedOption = options.find(opt => {
                const optVal = getOptionValue ? getOptionValue(opt, field) : (opt.id || opt.value || opt.kod_stavu || opt.kod || opt);
                return optVal == normalizedValue;
              });
              if (selectedOption && (selectedOption.atribut_objektu === 1 || selectedOption.atribut_objektu === '1')) {
                const cleanLabel = displayValue.replace('   (majetek)', '');
                return (
                  <>
                    <span>{cleanLabel}</span>
                    <span style={{
                      marginLeft: '8px',
                      fontSize: '0.75rem',
                      color: disabled ? '#6b7280' : '#dc2626',
                      fontWeight: disabled ? '400' : '500',
                      padding: '2px 6px',
                      backgroundColor: disabled ? '#f3f4f6' : '#fee2e2',
                      borderRadius: '4px',
                      border: disabled ? '1px solid #e5e7eb' : '1px solid #fca5a5'
                    }}>
                      (majetek)
                    </span>
                  </>
                );
              }
            }
            return displayValue;
          })()}
        </StableSelectValue>
        {isClearable && !disabled && hasValue && (
          <span
            role="button"
            tabIndex={0}
            onClick={(e) => {
              e.stopPropagation();
              const clearedValue = multiple ? [] : '';
              onChange(clearedValue);
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                e.stopPropagation();
                const clearedValue = multiple ? [] : '';
                onChange(clearedValue);
              }
            }}
            title="Smazat hodnotu"
            style={{
              position: 'absolute',
              right: '32px',
              top: '50%',
              transform: 'translateY(-50%)',
              background: 'none',
              border: 'none',
              padding: '4px',
              cursor: 'pointer',
              color: '#6b7280',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              width: '20px',
              height: '20px',
              borderRadius: '4px',
              transition: 'all 0.2s ease',
              zIndex: 2
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.background = '#f3f4f6';
              e.currentTarget.style.color = '#374151';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.background = 'none';
              e.currentTarget.style.color = '#6b7280';
            }}
          >
            <X size={14} />
          </span>
        )}
      </StableSelectButton>

      {isOpen && !disabled && (
        <StableSelectDropdown ref={dropdownRef}>
          <StableSelectSearchBox>
            <StableSelectSearchIcon>
              <Search size={16} />
            </StableSelectSearchIcon>
            <StableSelectSearchInput
              ref={searchInputRef}
              type="text"
              placeholder="Vyhledat..."
              value={searchTerm}
              onChange={(e) => {
                // Při ručním psaní resetuj voice flag
                if (e.nativeEvent.inputType && e.nativeEvent.inputType.startsWith('insert')) {
                  voiceInputFlagRef.current = false;
                }
                setSearchTerm(e.target.value);
              }}
              onClick={(e) => e.stopPropagation()}
              onKeyDown={(e) => {
                if (e.key === 'ArrowDown') {
                  // Šipka dolů - přejdi na první option
                  e.preventDefault();
                  if (filteredOptions.length > 0) {
                    const firstOption = dropdownRef.current?.querySelector('[role="option"]:not([tabindex="-1"])');
                    if (firstOption) {
                      firstOption.focus();
                    }
                  }
                } else if (e.key === 'ArrowUp') {
                  // Šipka nahoru - přejdi na poslední option
                  e.preventDefault();
                  if (filteredOptions.length > 0) {
                    const options = Array.from(dropdownRef.current?.querySelectorAll('[role="option"]:not([tabindex="-1"])') || []);
                    const lastOption = options[options.length - 1];
                    if (lastOption) {
                      lastOption.focus();
                    }
                  }
                } else if (e.key === 'Tab') {
                  // Pokud je dropdown otevřený, přejdi na první option místo zavření
                  if (filteredOptions.length > 0) {
                    e.preventDefault();
                    const firstOption = dropdownRef.current?.querySelector('[role="option"], [class*="SelectOption"]');
                    if (firstOption) {
                      firstOption.focus();
                    }
                  } else {
                    // Pokud nejsou žádné options, zavři dropdown a pokračuj na další prvek
                    setIsOpen(false);
                  }
                } else if (e.key === 'Escape') {
                  e.preventDefault();
                  setIsOpen(false);
                  // Vrať focus na select button
                  if (buttonRef.current) {
                    buttonRef.current.focus();
                  }
                } else if (e.key === 'Enter') {
                  e.preventDefault();
                  e.stopPropagation();
                }
              }}
            />
          </StableSelectSearchBox>

          {loading ? (
            <StableSelectOption>{loadingText}</StableSelectOption>
          ) : filteredOptions.length > 0 ? (
            filteredOptions.map((option, index) => {
              const optionValue = getOptionValue ? getOptionValue(option, field) : (option.id || option.value || option);
              let optionLabel;

              if (getOptionLabel) {
                optionLabel = getOptionLabel(option, field);
              } else {
                // Fallback pro různé typy objektů
                if (field === 'strediska' || field === 'strediska_kod') {
                  optionLabel = option.label || option.name || option.nazev_stavu || String(option);
                } else if (field === 'lp_kod') {
                  optionLabel = option.cislo_lp ? `${option.cislo_lp} - ${option.nazev_uctu || ''}` : option.label || String(option);
                } else {
                  optionLabel = option.label || option.nazev || option.name || String(option);
                }
              }

              const selected = isSelected(option);
              const level = option.level || 0;
              const isHeader = option.isHeader || (level === 0 && !option.value && !option.id);
              
              // 🏷️ Check if this is druh_objednavky with majetek flag
              const isMajetekOption = field === 'druh_objednavky_kod' && (option.atribut_objektu === 1 || option.atribut_objektu === '1');

              return (
                <StableSelectOption
                  key={optionValue || index}
                  selected={selected}
                  level={level}
                  isHeader={isHeader}
                  tabIndex={isHeader ? -1 : 0}
                  role="option"
                  aria-selected={selected}
                  onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    // Neumožni kliknout na header
                    if (!isHeader) {
                      handleOptionClick(option);
                    }
                  }}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      if (!isHeader) {
                        handleOptionClick(option);
                      }
                    } else if (e.key === 'ArrowDown') {
                      // Šipka dolů - přejdi na další option
                      e.preventDefault();
                      const options = Array.from(dropdownRef.current?.querySelectorAll('[role="option"]:not([tabindex="-1"])') || []);
                      const currentIdx = options.indexOf(e.target);
                      const nextIdx = currentIdx + 1;
                      if (nextIdx < options.length) {
                        options[nextIdx].focus();
                      } else {
                        // Cyklicky na začátek
                        options[0]?.focus();
                      }
                    } else if (e.key === 'ArrowUp') {
                      // Šipka nahoru - přejdi na předchozí option
                      e.preventDefault();
                      const options = Array.from(dropdownRef.current?.querySelectorAll('[role="option"]:not([tabindex="-1"])') || []);
                      const currentIdx = options.indexOf(e.target);
                      const prevIdx = currentIdx - 1;
                      if (prevIdx >= 0) {
                        options[prevIdx].focus();
                      } else {
                        // Cyklicky na konec nebo zpět do search inputu
                        if (searchInputRef.current) {
                          searchInputRef.current.focus();
                        } else {
                          options[options.length - 1]?.focus();
                        }
                      }
                    } else if (e.key === 'Escape') {
                      e.preventDefault();
                      setIsOpen(false);
                      if (buttonRef.current) {
                        buttonRef.current.focus();
                      }
                    } else if (e.key === 'Tab') {
                      // Nech prohlížeč zvládat tab - přejde na další option nebo zavře dropdown
                      const options = Array.from(dropdownRef.current?.querySelectorAll('[role="option"]:not([tabindex="-1"])') || []);
                      const currentIdx = options.indexOf(e.target);

                      if (e.shiftKey) {
                        // Shift+Tab - pokud jsme na první option, vrať se na search input
                        if (currentIdx === 0) {
                          e.preventDefault();
                          if (searchInputRef.current) {
                            searchInputRef.current.focus();
                          }
                        }
                      } else {
                        // Tab - pokud jsme na poslední option, zavři dropdown a pokračuj dál
                        if (currentIdx === options.length - 1) {
                          e.preventDefault();
                          setIsOpen(false);
                          // Nech hlavní tab handler najít další prvek ve formuláři
                        }
                      }
                    }
                  }}
                >
                  {multiple && !isHeader && (
                    <input
                      type="checkbox"
                      checked={selected}
                      readOnly
                      onChange={() => {}} // Prázdný handler aby nedával warning
                    />
                  )}
                  {isMajetekOption ? (
                    <>
                      <span>{optionLabel.replace('   (majetek)', '')}</span>
                      <span style={{
                        marginLeft: '8px',
                        fontSize: '0.75rem',
                        color: '#dc2626',
                        fontWeight: '500',
                        padding: '2px 6px',
                        backgroundColor: '#fee2e2',
                        borderRadius: '4px',
                        border: '1px solid #fca5a5'
                      }}>
                        (majetek)
                      </span>
                    </>
                  ) : (
                    <span>{optionLabel}</span>
                  )}
                </StableSelectOption>
              );
            })
          ) : (
            <StableSelectOption>Žádné výsledky</StableSelectOption>
          )}
        </StableSelectDropdown>
      )}
    </StableSelectWrapper>
  );
}, (prevProps, nextProps) => {
  // Custom comparison funkce pro React.memo
  // Vrací true pokud jsou props STEJNÉ (skip re-render)
  // Vrací false pokud jsou props RŮZNÉ (provede re-render)

  // Porovnej primitivní hodnoty
  if (prevProps.value !== nextProps.value) return false;
  if (prevProps.placeholder !== nextProps.placeholder) return false;
  if (prevProps.disabled !== nextProps.disabled) return false;
  if (prevProps.hasError !== nextProps.hasError) return false;
  if (prevProps.required !== nextProps.required) return false;
  if (prevProps.field !== nextProps.field) return false;
  if (prevProps.loading !== nextProps.loading) return false;
  if (prevProps.loadingText !== nextProps.loadingText) return false;
  if (prevProps.multiple !== nextProps.multiple) return false;
  if (prevProps.hasTriedToSubmit !== nextProps.hasTriedToSubmit) return false;

  // Porovnej arrays (options) - kontrola délky a referencí
  if (prevProps.options.length !== nextProps.options.length) return false;
  // Pro performance nekontrolujeme deep equality jednotlivých items
  // stačí porovnat reference pole (které se mění při načtení dat)
  if (prevProps.options !== nextProps.options) return false;

  // Icon může být React element, takže použijeme reference check
  if (prevProps.icon !== nextProps.icon) return false;

  // onChange, onBlur, getOptionLabel, getOptionValue jsou funkce
  // Pokud jsou zmemoizované přes useCallback, reference zůstane stejná
  // Zde je nemůžeme deep compare, tak použijeme reference check
  if (prevProps.onChange !== nextProps.onChange) return false;
  if (prevProps.onBlur !== nextProps.onBlur) return false;
  if (prevProps.getOptionLabel !== nextProps.getOptionLabel) return false;
  if (prevProps.getOptionValue !== nextProps.getOptionValue) return false;

  // Všechny props jsou stejné - skip re-render
  return true;
});
